G["forever/alliance/03-darkshore"] = {
	["Back to {npc:11802} in {area:2361}, then {npc:11800} there flies Druids straight to {area:702}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "回到{area:2361}的{npc:11802}处，再找那里的{npc:11800}，他能直接把德鲁伊送到{area:702}。{npc:11802}在他那栋楼的楼上：从里面上楼，箭头分不清楼层。",
	["Blackwood Pathfinder"] = "黑木探路者",
	["Blackwood Windtalker"] = "黑木语风者",
