G["forever/class/mage/teleports-alliance"] = {
	["At 20 go to the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:2485}, the portal trainer, stands at the very top: climb the spiral ramp and take the portal near the top. She teaches {spell:3561} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor; {npc:1308} sells them at the foot of the tower), so carry a few."] = "20级时去巫师圣殿，即{zone:1453}的{object:2101}中的紫罗兰高塔。传送门训练师{npc:2485}就在最顶层：沿螺旋坡道爬上去，乘靠近顶部的传送门。她以20银教授{spell:3561}。每次传送消耗一个{item:17031}（任意施法材料商10银；{npc:1308}在塔底出售），所以多带几个。",
	["At 30. Take the boat from {area:17203} to {area:442} in {zone:1439}, then the boat to {area:702} and the pink portal up into {zone:1457}. {npc:4165}, the portal trainer, teaches {spell:3565} for 80 silver."] = "30级时。从{area:17203}乘船到{zone:1439}的{area:442}，再乘船到{area:702}，然后走粉色传送门进入{zone:1457}。传送门训练师{npc:4165}以80银教授{spell:3565}。",
	["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:2485} has {spell:10059} at the top of the Wizard's Sanctum; then the tram to {npc:2489} in {zone:1455}'s {object:32362} for {spell:11416}."] = "40级时传送门训练师会教传送门：一道整队都能穿过的传送门，每个1金50银。每道传送门消耗一个{item:17032}（任意施法材料商20银）。{npc:2485}在巫师圣殿顶层教{spell:10059}；然后乘地铁到{zone:1455}的{object:32362}找{npc:2489}学{spell:11416}。",
	["At 50 {npc:4165} in {zone:1457} teaches the last one, {spell:11419}, for 3 gold 20 silver. Use your {spell:3565} to get there."] = "50级时{zone:1457}的{npc:4165}教授最后一个{spell:11419}，3金20银。用你的{spell:3565}过去。",
	["Mage"] = "法师",
	["Portals to {zone:1453} and {zone:1455}"] = "通往{zone:1453}和{zone:1455}的传送门",
	["Take the {area:2257} from {zone:1453}'s {object:28027} to {zone:1455}. {npc:2489}, the portal trainer, stands with the mage trainers in the {object:32362} at the back of the city: {spell:3562}, 20 silver."] = "从{zone:1453}的{object:28027}乘{area:2257}到{zone:1455}。传送门训练师{npc:2489}与法师训练师一起站在城市后部的{object:32362}里：{spell:3562}，20银。",
	["Teleports and Portals (Alliance)"] = "传送与传送门（联盟）",
	["Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer."] = "20级和30级的城市传送、40级和50级的团队传送门，都向各城市的传送门训练师学习。",
	["{item:17031}, 10s each"] = "{item:17031}，每个10银",
	["{item:17032}, 20s each"] = "{item:17032}，每个20银",
}

G["forever/class/priest/desperate-prayer-and-chastise"] = {
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455} (the {area:2257} from {zone:1453}'s {object:28027})."] = "10级时在{zone:1429}，{area:87}狮王之傲旅店楼上的{npc:377}会给你一封给{zone:1455}的{npc:11406}的{quest:5634}信件（从{zone:1453}的{object:28027}乘{area:2257}）。",
	["At 10 in {zone:1438}, {npc:3600}, in the building at the north edge of {area:186}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455}."] = "10级时在{zone:1438}，{area:186}北边缘建筑里的{npc:3600}会给你一封给{zone:1455}的{npc:11406}的{quest:5634}信件。",
	["At 10 in {zone:1453}, {npc:11397}, the priest trainer in the Park (the night elf quarter on the city's west side), hands you a {quest:5634} letter for {npc:11406} in {zone:1455}. {npc:376} in the Cathedral has none for Dwarves."] = "10级时在{zone:1453}，公园（城市西侧的暗夜精灵区）里的牧师训练师{npc:11397}会给你一封给{zone:1455}的{npc:11406}的{quest:5634}信件。大教堂里的{npc:376}没有给矮人的。",
	["At 10 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455}."] = "10级时在{zone:1457}，月神殿上层阳台{npc:7999}旁的{npc:11401}会给你一封给{zone:1455}的{npc:11406}的{quest:5634}信件。",
	["At 10, go to {npc:11406} in the {object:32386}, in {zone:1455}'s {object:32362} (north-west of the city): he gives {quest:5634} and takes it back at once. No letter needed. {quest:5634} heals you instantly, costs no mana and has a long cooldown: keep it for emergencies."] = "10级时，去{zone:1455}的{object:32362}（城市西北）里的{object:32386}找{npc:11406}：他会给你{quest:5634}并立刻收回。不需要信件。{quest:5634}会瞬间治疗你，不耗法力且冷却很长：留着应急。",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:5634} letter for {npc:11406}. {area:131} is on the road up to {zone:1455}."] = "10级时，{area:131}的{area:2102}里的牧师训练师{npc:1226}会给你一封给{npc:11406}的{quest:5634}信件。{area:131}在通往{zone:1455}的路上。",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:5641} letter for {npc:11406} in {zone:1455} (the {area:2257} from the {object:28027})."] = "20级时在{zone:1453}，光明大教堂祭坛旁的{npc:376}会给你一封给{zone:1455}的{npc:11406}的{quest:5641}信件（从{object:28027}乘{area:2257}）。",
	["At 20 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a {quest:5641} letter for {npc:11406} in {zone:1455}."] = "20级时在{zone:1457}，月神殿上层阳台{npc:7999}旁的{npc:11401}会给你一封给{zone:1455}的{npc:11406}的{quest:5641}信件。",
	["At 20, {npc:11406} in the {object:32386} teaches {quest:5641} with a quest he gives and takes back at once. Forever renamed it from A Lack of Fear: {quest:5641} damages a humanoid and roots it for 2 seconds (instant, 2-minute cooldown), and every priest now trains {spell:6346}."] = "20级时，{object:32386}里的{npc:11406}用一个给了就立刻收回的任务教你{quest:5641}。Forever 把它从“毫无畏惧”改了名：{quest:5641}对一个人形生物造成伤害并定身2秒（瞬发，2分钟冷却），现在每个牧师都会训练{spell:6346}。",
	["Follow the road up from {area:131} into {zone:1455} and west to the {object:32362}: {npc:11406} in the {object:32386} takes the letter and teaches {quest:5637}. The letter tells you to head to {zone:1453}, but the one who wants you is Rohan in {zone:1455}."] = "顺着从{area:131}通往{zone:1455}的路向上，再向西到{object:32362}：{object:32386}里的{npc:11406}收下信件并教你{quest:5637}。信上让你去{zone:1453}，但真正要找你的是{zone:1455}的罗翰。",
	["Hand Alathea's letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: from {zone:1457}, the boats via {area:702} and {area:442} to {area:150}, then the road north through the {zone:1437} and {zone:1432} (or the boat to {area:17203} and the {area:2257})."] = "把阿拉希亚的信交给{zone:1455}的{object:32362}中{object:32386}里的{npc:11406}：从{zone:1457}出发，经{area:702}和{area:442}乘船到{area:150}，然后沿路向北穿过{zone:1437}和{zone:1432}（或乘船到{area:17203}再乘{area:2257}）。",
	["Hand Laurena's letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: he teaches {quest:5645}."] = "把劳伦娜的信交给{zone:1455}的{object:32362}中{object:32386}里的{npc:11406}：他教你{quest:5645}。",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: from {zone:1438}, the boat from {area:702} to {area:442}, the boat to {area:150} and the road north through the {zone:1437} and {zone:1432} (or the boat to {area:17203} and the {area:2257})."] = "把信交给{zone:1455}的{object:32362}中{object:32386}里的{npc:11406}：从{zone:1438}出发，从{area:702}乘船到{area:442}，再乘船到{area:150}并沿路向北穿过{zone:1437}和{zone:1432}（或乘船到{area:17203}再乘{area:2257}）。",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: its text says {zone:1453}, but Rohan is in {zone:1455}. From {zone:1457}, the portal down to {area:702}, the boat to {area:442}, then {area:150} and the road north (or {area:17203} and the {area:2257})."] = "把信交给{zone:1455}的{object:32362}中{object:32386}里的{npc:11406}：信上写的是{zone:1453}，但罗翰在{zone:1455}。从{zone:1457}出发，走传送门下到{area:702}，乘船到{area:442}，再到{area:150}沿路向北（或{area:17203}和{area:2257}）。",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "把信交给{zone:1455}的{object:32362}中{object:32386}里的{npc:11406}：从{zone:1453}的{object:28027}乘{area:2257}。",
	["Priest"] = "牧师",
	["The Dwarf priest spells: {quest:5634} at 10, {quest:5641} (new in Forever) at 20. Free, no objectives."] = "矮人牧师的技能：10级{quest:5634}，20级{quest:5641}（Forever 新增）。免费，无任务目标。",
	["This letter also goes to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}."] = "这封信也是交给{zone:1455}的{object:32362}中{object:32386}里的{npc:11406}。",
