G["forever/class/shaman/call-of-earth-alliance"] = {
	["Back to Teo inside {area:77}. He hands you the {item:6635}: do not drink it yet."] = "回到{area:77}里的提奥。他会给你{item:6635}：先别喝。",
	["Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "把{item:6656}带回{area:77}里的提奥。把{item:5175}永久留在背包里：每个大地图腾都需要它。",
	["Iceclaw Bear Pendants"] = "冰爪熊吊坠",
	["Lost the {quest:94472}?"] = "{quest:94472}丢了？",
	["Only if the {quest:94472} is gone from your bags (drunk away from the stone, or sold): Teo gives you another."] = "只有当{quest:94472}从你背包里消失时（在石块以外的地方喝掉或卖掉）：提奥会再给你一个。",
	["Shaman"] = "萨满祭司",
	["The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of {area:77}, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes."] = "霜鬃巨魔幼崽（3-4级）占据{area:77}西边和西南的雪坡，霜鬃新兵（3-4级，会远程投掷寒冰箭）扎营在其南边。两者都携带吊坠；约三分钟刷新。",
	["The Spirit Stone"] = "灵魂之石",
	["The Spirit Stone stands on a snowy ridge north-west of {area:77}. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the {item:6635} and speak to the {npc:5891} before it fades."] = "灵魂之石立在{area:77}西北的雪脊上。小路很容易错过：它从谷底爬上山丘；在接近顶部的小营地左转就能看见石头。站在石旁，喝下{item:6635}，趁它消失前与{npc:5891}交谈。",
	["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "你的{item:5175}：没有它就无法施放任何大地图腾。4级时会连同{spell:8071}一起获得。",
	["it hands you the {item:6656}: keep it"] = "它会给你{item:6656}：留着",
	["the level 4 shaman spells"] = "4级萨满法术",
	["{item:6635}, beside the Spirit Stone"] = "{item:6635}，灵魂之石旁",
	["{npc:257446} trains shamans inside {area:77}, the hall at the south end of {area:132}. The quest opens at level 4. Never took it and now 10 or more? {npc:258098} in {zone:1455} or {npc:258113} in {area:131} gives you {quest:94373}, a pointer back to Teo: take it for the experience on the way."] = "{npc:257446}在{area:132}南端大厅、{area:77}内训练萨满。任务4级开放。从没接过而现在已10级以上？{zone:1455}的{npc:258098}或{area:131}的{npc:258113}会给你{quest:94373}，指向提奥：顺路接下拿经验。",
	["{npc:257446}: a new {quest:94472}"] = "{npc:257446}：新的{quest:94472}",
	["{npc:257446}: {spell:8071} and your {item:5175}"] = "{npc:257446}：{spell:8071}与你的{item:5175}",
	["{quest:94373} (Alliance)"] = "{quest:94373}（联盟）",
}

G["forever/collectibles/mounts/alliance/swift-horse"] = {
	["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "任何联盟种族都能买这些马，但骑乘还需要{spell:824}，只有人类能随{skill:762}获得。其他种族达到{faction:72}崇拜后可由{npc:4732}教授（暴风城声望攻略给出了路线）。在此之前，别给这个角色买马。",
	["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 60 {npc:4732} teaches Journeyman {skill:762} to Humans for 1,000g (10% less at Honored with {faction:72}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift horse costs 200g here."] = "{npc:4732}和{npc:384}的马厩在{zone:1429}东部的{area:88}。60级时{npc:4732}以1000金向人类教授中级{skill:762}（{faction:72}尊敬时减10%）；暴雪称会附带一匹马。其他种族在本族的骑术训练师处学习。这里的迅捷马每匹200金。",
	["{spell:824} for other races"] = "其他种族的{spell:824}",
}

G["forever/reputation/stormwind"] = {
	["About 1,150 {faction:72} reputation from level 52-58 quests at {area:3197} and in the {zone:1428}"] = "在{area:3197}和{zone:1428}做52-58级任务可获得约1150点{faction:72}声望",
	["About 4,500 {faction:72} reputation from low-level quests in Elwynn and the {area:717} (in Classic, a fifth of it at 60)"] = "在艾尔文森林和{area:717}做低等级任务可获得约4500点{faction:72}声望（经典版中60级时只有五分之一）",
	["Andorhal Tower Four"] = "安多哈尔四号塔",
	["Andorhal Tower One"] = "安多哈尔一号塔",
	["Andorhal Tower Three"] = "安多哈尔三号塔",
	["Andorhal Tower Two"] = "安多哈尔二号塔",
	["Andorhal and {area:199}"] = "安多哈尔与{area:199}",
	["Arcane Explainer"] = "奥术讲解者",
	["Black Broodling"] = "黑色雏龙",
	["Black Dragonspawn"] = "黑色龙人",
	["Black Drake"] = "黑色幼龙",
	["Black Wyrmkin"] = "黑色龙兽",
	["Cloth, the {zone:1422}' cauldron quests and the Elwynn hubs: the quests pay most while you level."] = "布料、{zone:1422}的大锅任务以及艾尔文森林各据点：升级过程中任务给的声望最多。",
	["Defias Convict"] = "迪菲亚罪犯",
	["Defias Insurgent"] = "迪菲亚暴徒",
	["Defias Prisoner"] = "迪菲亚囚犯",
	["Defias Rogue Wizard"] = "迪菲亚流氓法师",
	["Eastvale"] = "东谷",
	["Eastvale: Defias Rogue Wizards"] = "东谷：迪菲亚流氓法师",
	["Eastvale: hand in"] = "东谷：交任务",
	["Eastvale: the work"] = "东谷：干活",
	["Exalted with {faction:72}: in Classic, other races may buy the horses"] = "{faction:72}崇拜：经典版中其他种族即可购买这些马",
	["Honored: in Classic Stormwind's vendors take 10% off for you, {npc:384}'s horses (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 {item:14047}."] = "尊敬：经典版中暴风城商人会给你打九折，包括{npc:384}的马（20金，迅捷马200金）；Forever 尚未确定，攻略站点称友善时5%，崇拜时升至20%。尊敬到崇敬需要12000点声望：240次上交，4800个{item:14047}。",
	["Inside the {area:717}"] = "{area:717}内",
	["Kill the prisoners, convicts and insurgents in the cells; the Red Wool Bandanas drop from the Defias inside. {npc:1716} waits in the far end."] = "杀掉牢房里的囚犯、罪犯和暴徒；红色毛纺头巾由里面的迪菲亚掉落。{npc:1716}在最深处等你。",
	["Kobold Geomancer"] = "狗头人地卜师",
	["Kobold Laborer"] = "狗头人劳工",
	["Kobold Vermin"] = "狗头人害兽",
	["Kobold Worker"] = "狗头人工人",
	["Lady Katrana Prestor"] = "卡特拉娜·普瑞斯托女士",
	["Mark the four watchtowers around Andorhal, north of the camp, with the {item:12815} at each door. {npc:11075} guards the cauldron at {area:199}, west of Andorhal; his key opens it. {npc:10778}'s ghost wanders by the Felstone farmhouse, and her parcel lies inside: it goes to {faction:72} for 150 more."] = "用{item:12815}在营地以北安多哈尔周围四座瞭望塔的每道门上做标记。{npc:11075}守着安多哈尔以西{area:199}的大锅；他的钥匙能打开。{npc:10778}的鬼魂在邪石农舍旁游荡，她的包裹就在里面：交给{faction:72}可再得150点。",
	["Mark {npc:10902} with the {item:12815}"] = "用{item:12815}标记{npc:10902}",
	["Mark {npc:10903} with the {item:12815}"] = "用{item:12815}标记{npc:10903}",
	["Mark {npc:10904} with the {item:12815}"] = "用{item:12815}标记{npc:10904}",
	["Mark {npc:10905} with the {item:12815}"] = "用{item:12815}标记{npc:10905}",
	["Northshire: Echo Ridge, {npc:103} and the vineyard"] = "北郡：回音山脊、{npc:103}与葡萄园",
	["Northshire: back at the abbey"] = "北郡：回到修道院",
	["Northshire: kobolds, wolves and bandanas"] = "北郡：狗头人、狼与头巾",
	["Northshire: last hand-in"] = "北郡：最后一次上交",
	["Northshire: second hand-in"] = "北郡：第二次上交",
	["Northshire: the books end in {area:87}"] = "北郡：书在{area:87}结束",
	["Northshire: the mine and the books"] = "北郡：矿洞与书",
	["Optional: eastern Elwynn, around {npc:261} on the bridge and the {area:91}, about 1,000 reputation (200 at a fifth) in 40 minutes at 60. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：艾尔文森林东部，桥上的{npc:261}和{area:91}附近，60级时约40分钟可得1000点声望（五分之一为200）。经典版中低于你6级以上的任务给的更少（60级时为五分之一）；Forever 测试报告称会全额给。第一次上交就能看出来：若只给五分之一，就跳过这些据点。跳过这一步即跳过该据点。",
	["Optional: four quick deliveries inside {faction:72} for 200 reputation (40 at a fifth) in about five minutes. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：在{faction:72}城内送四次快件，约五分钟可得200点声望（五分之一为40）。经典版中低于你6级以上的任务给的更少（60级时为五分之一）；Forever 测试报告称会全额给。第一次上交就能看出来：若只给五分之一，就跳过这些据点。跳过这一步即跳过该据点。",
	["Optional: the Human start valley north of {area:87}: about 1,600 reputation (320 at a fifth) in 40 minutes at 60, the best rate of the hubs. {npc:823} and {npc:197} stand at {area:24}. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:87}以北的人类新手山谷：60级时约40分钟得1600点声望（五分之一为320），是各据点中效率最高的。{npc:823}和{npc:197}站在{area:24}。经典版中低于你6级以上的任务给的更少（60级时为五分之一）；Forever 测试报告称会全额给。第一次上交就能看出来：若只给五分之一，就跳过这些据点。跳过这一步即跳过该据点。",
	["Optional: the {area:717} is {faction:72}'s prison, a dungeon in the canals of the {object:2101}. At 60 you clear it alone in ten minutes: 300 reputation (60 at a fifth). {npc:1719} stands at the gate, {npc:1721} in {object:2100}. Two more {area:717} quests start outside the city, 100 each, if you pass by: What Comes Around... ({npc:1696}) from {npc:859} in {area:69} and Crime and Punishment ({npc:1663}) from {npc:270} in {area:42}. (The Stockade Riots, 100 more, needs the Unsent Letter from {npc:639} in the {area:1581} first.) In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:717}是{faction:72}的监狱，位于{object:2101}运河中的地下城。60级时十分钟即可单刷：300点声望（五分之一为60）。{npc:1719}站在门口，{npc:1721}在{object:2100}。还有两个{area:717}任务在城市外接取，各100点，若顺路可做：因果报应……（{npc:1696}）来自{area:69}的{npc:859}，罪与罚（{npc:1663}）来自{area:42}的{npc:270}。（监狱暴动，另100点，需先拿到{area:1581}里{npc:639}的未寄出的信。）经典版中低于你6级以上的任务给的更少（60级时为五分之一）；Forever 测试报告称会全额给。第一次上交就能看出来：若只给五分之一，就跳过这些据点。跳过这一步即跳过该据点。",
	["Optional: {area:87}, Westbrook and the farms south of {area:87}: about 1,450 reputation (290 at a fifth) in an hour at 60. {npc:240}, {npc:241} and {npc:253} stand around the Lion's Pride Inn. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "可选：{area:87}、西泉和{area:87}以南的农场：60级时约一小时得1450点声望（五分之一为290）。{npc:240}、{npc:241}和{npc:253}站在狮王之傲旅店附近。经典版中低于你6级以上的任务给的更少（60级时为五分之一）；Forever 测试报告称会全额给。第一次上交就能看出来：若只给五分之一，就跳过这些据点。跳过这一步即跳过该据点。",
	["Prowler"] = "徘徊者",
	["Reputation · Cities"] = "声望 · 城市",
	["Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, {npc:384} at {area:88} sells her horses to other races in Classic; the Horse and Swift Horse guides cover them."] = "崇敬到崇拜需要21000点声望：420次上交，8400个{item:14047}。崇拜后，经典版中{area:88}的{npc:384}会向其他种族出售她的马；马与迅捷马攻略中有介绍。",
	["Skeletal Flayer"] = "骷髅剥皮者",
	["Slavering Ghoul"] = "流涎食尸鬼",
	["Speak with {npc:1749}"] = "与{npc:1749}交谈",
	["The Kobold Workers are in {area:34} north of the abbey; {npc:103} stands in the Defias camp east of the vineyard; {quest:3904} crates lie in the vineyard; the rats carrying the {object:83763} run about the abbey grounds."] = "狗头人工人在修道院以北的{area:34}；{npc:103}站在葡萄园东边的迪菲亚营地；{quest:3904}的木箱在葡萄园里；带着{object:83763}的老鼠在修道院一带跑动。",
	["The Stonefields' farm and the Maclures' farm lie on either side of the road south of {area:87}. {quest:87} guards the back of {area:57}; {npc:330} the boar roams the {area:62}."] = "石田家和麦克卢尔家的农场位于{area:87}以南道路两侧。{quest:87}守着{area:57}的后方；野猪{npc:330}在{area:62}游荡。",
	["The farms south of {area:87}"] = "{area:87}以南的农场",
	["The murlocs along the river south of the bridge drop the fins; Prowlers and Young Forest Bears roam the woods; the Defias around the Brackwell farm and the {area:91} carry the bandanas; the enchanting supplies lie in their camps north of the tower; the Kobold Geomancers dig at {area:54}; the tools and the river finds lie along the river north of the logging camp."] = "桥南沿河的鱼人掉落鱼鳍；徘徊者与幼年森林熊在林中游荡；布拉克威尔农场和{area:91}附近的迪菲亚携带头巾；附魔材料在他们的营地、塔以北；狗头人地卜师在{area:54}挖掘；工具和河边物品散落在伐木营地以北的河岸。",
	["The {npc:6} dig at the camp north of the abbey; the wolves roam the valley; the Defias at the vineyard east of the abbey drop the bandanas. Keep any {item:247834} a kobold drops: it starts Forever's book chain."] = "{npc:6}在修道院以北的营地挖掘；狼群在山谷中游荡；修道院以东葡萄园的迪菲亚掉落头巾。狗头人掉落的{item:247834}都留着：它能开启 Forever 的书本任务链。",
	["These quests are level 52 to 58, so they pay in full at 60, or nearly. {npc:10838} and {npc:11053} at {area:3197}, in the south of the {zone:1422}, send you against the four Scourge cauldrons: 820 {faction:72} reputation in all and 600 {object:92525} on the side (in Classic about 690 {faction:72} at 60, as the first quests are level 52 and 53). The Skeletal Flayers and Slavering Ghouls roam the fields north of the camp."] = "这些任务为52到58级，所以60级时仍能全额或接近全额。{zone:1422}南部{area:3197}的{npc:10838}和{npc:11053}会派你去对付四口天灾大锅：共820点{faction:72}声望，另有600个{object:92525}（经典版中60级时约690点{faction:72}，因为最初的任务为52和53级）。骷髅剥皮者和流涎食尸鬼在营地以北的田野游荡。",
	["With a group the chain goes on into {area:1584}: {npc:9023}, Jail Break! and The Great Masquerade back in {faction:72} pay about 750 {faction:72} more, Maxwell's Mission (Lower {area:1583}) 250, Delivery to Ridgewell 135. Order Must Be Restored ({npc:11878} in the {zone:1423}) pays 200, The Key to {area:2057} 200; Onyxia's head 400 and Nefarian's 200 when the raids open."] = "组队后任务链会继续进入{area:1584}：{npc:9023}、越狱！以及回到{faction:72}的化装舞会共约再给750点{faction:72}，麦克斯韦的任务（下层{area:1583}）250点，送往山脊维尔的货物135点。必须恢复秩序（{zone:1423}的{npc:11878}）给200点，{area:2057}的钥匙200点；团队副本开放后，奥妮克希亚的头400点，奈法利安的头200点。",
	["Young Forest Bear"] = "幼年森林熊",
	["opens with Thomas' report"] = "从托马斯的报告开始",
	["the {object:176361}"] = "{object:176361}",
	["the {object:176392}"] = "{object:176392}",
	["the {object:176393}"] = "{object:176393}",
	["the {object:177289}"] = "{object:177289}",
	["walk into the mine"] = "走进矿洞",
	["{area:3197}: done"] = "{area:3197}：完成",
	["{area:3197}: the {area:202}"] = "{area:3197}：{area:202}",
	["{area:57} is south of {area:87}, {area:54} north-east of it. The kobolds in both drop the candles and the {item:773}; the wolves around {area:87} the pelts."] = "{area:57}位于{area:87}以南，{area:54}位于其东北。两处的狗头人都掉蜡烛和{item:773}；{area:87}周围的狼掉毛皮。",
	["{area:69}: Solomon again"] = "{area:69}：再找所罗门",
