	["Fly to {area:976}"] = "飞往{area:976}",
	["Follow the road south-west out of the pass to {area:3425}. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "沿路向西南出山口到{area:3425}。{npc:15189}站在他建筑的楼上：从里面上楼，箭头无法分辨楼层。",
	["For {area:1377}: keep it"] = "留着给{area:1377}",
