	["Frenzied Plaguehound"] = "狂乱瘟疫犬",
	["Frenzied Pterrordax"] = "狂乱翼手龙",
	["From Theramore, ride west into the {area:17} and north up the coast to {area:392}."] = "从塞拉摩向西骑进入{area:17}，再沿海岸北上到{area:392}。",
	["Huntsman Radley"] = "猎人拉德利",
	["If you skipped The {item:9328}, grind here to level 56.89 to stay on the route's plan."] = "如果你跳过了{item:9328}，就在这里刷到56.89级，以保持路线的计划。",
	["Inside"] = "室内",
	["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "把{npc:9999}向北带到{area:541}。他昏倒时，对他使用{item:11804}唤醒他。",
