	["Ranshalla in {area:618}: keep it"] = "{area:618}的兰莎拉：保留",
	["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "沿斜坡骑下进入环形山：{npc:9619}在坡底扎营。",
	["Ride east to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "向东骑到{area:2738}内的{area:2742}塔；爬上塔，击杀为那块布满硬壳的物件而出现的伏击者。",
	["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "向东骑到{area:537}，爬上去，在顶部附近的熔岩喷口使用{npc:10541}。",
	["Ride east to {npc:13220}."] = "向东骑到{npc:13220}。",
	["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "沿东侧向北骑到大猩猩高原。55级大猩猩{npc:9622}待在最深处的洞穴里：先清掉洞口的大猩猩。",
	["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby.
