	["Any {quest:94825} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "任何{quest:94825}信件都交给{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}。",
	["Any {quest:94826} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "任何{quest:94826}信件都交给{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}。",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}."] = "10级时在{zone:1429}，{area:87}狮王之傲旅店楼上的{npc:377}会交给你一封给{npc:258785}（位于{zone:1455}）的{quest:94817}信件。",
	["At 10 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94817} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "10级时在{zone:1453}，光明大教堂祭坛旁的{npc:376}会交给你一封给{npc:258785}（位于{zone:1455}）的{quest:94817}信件（乘{object:28027}的{area:2257}）。",
	["At 10, go to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362} (north-west of the city), right beside {npc:11406}: she gives {quest:94817} and takes it back at once. No letter needed. {quest:94817} confuses up to five enemies around you for 3 seconds (any damage wakes them) on a 2-minute cooldown: time to step back and heal, or to run."] = "10级时，前往{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}（城市西北），就在{npc:11406}旁边：她会给出{quest:94817}并立刻收回。不需要信。{quest:94817}使周围最多五名敌人迷惑3秒（任何伤害都会唤醒他们），冷却2分钟：用来后撤治疗或逃跑。",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}. {area:131} is on the road up to the city."] = "10级时，{area:131}的{area:2102}内的牧师训练师{npc:1226}会交给你一封给{npc:258785}（位于{zone:1455}）的{quest:94817}信件。{area:131}在通往城市的路上。",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94818} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "20级时在{zone:1453}，光明大教堂祭坛旁的{npc:376}会交给你一封给{npc:258785}（位于{zone:1455}）的{quest:94818}信件（乘{object:28027}的{area:2257}）。",
	["At 20, {npc:258785} in the {object:32386} teaches {quest:94818} with a quest she gives and takes back at once. {quest:94818} wards a friend for 30 seconds: if they drop below 35% health, they get a shield and a heal over time at once (it stacks with {spell:139} and {spell:17}). 5-minute cooldown."] = "20级时，{object:32386}中的{npc:258785}通过一个她给出并立刻收回的任务教授{quest:94818}。{quest:94818}为一个友方提供30秒守护：如果其生命值降到35%以下，立刻获得一个护盾和持续治疗（可与{spell:139}和{spell:17}叠加）。冷却5分钟。",
	["Follow the road up from {area:131} into {zone:1455} and to the {object:32362}: {npc:258785} in the {object:32386} takes the letter and teaches {quest:94824}."] = "沿路从{area:131}向上进入{zone:1455}，到达{object:32362}：{object:32386}中的{npc:258785}收下信件并教授{quest:94824}。",
	["Hand Laurena's letter to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "把劳瑞娜的信交给{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}：乘{zone:1453}的{object:28027}的{area:2257}。",
	["Hand the letter to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "把信交给{zone:1455}的{object:32362}内、{object:32386}中的{npc:258785}：乘{zone:1453}的{object:28027}的{area:2257}。",
	["Priest"] = "牧师",
	["The Gnome priest spells, new in Forever: {quest:94817} at 10, {quest:94818} at 20. Free, no objectives."] = "侏儒牧师法术，Forever 新增：10级{quest:94817}，20级{quest:94818}。免费，无目标。",
	["{npc:1226}: take his {quest:94817} letter"] = "{npc:1226}：接取他的{quest:94817}信件",
	["{npc:376}: take her {quest:94817} letter"] = "{npc:376}：接取她的{quest:94817}信件",
