G["forever/class/shaman/call-of-fire-alliance"] = {
	["At 10 {npc:258113}, the shaman trainer in {area:131}, or {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:257597}."] = "10级时，{area:131}的萨满训练师{npc:258113}，或{zone:1455}的萨满训练师{npc:258098}，会派你去找{npc:257597}。",
	["Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "穿过南门隧道返回，沿小路向上到{npc:257597}的洞穴。把{item:5176}永久留在背包里：每个火焰图腾都需要它。",
	["Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch."] = "沿小路返回{npc:257808}处。他用焦油和袋子制作{item:6636}：把它和火把一起留着。",
	["Click the {object:61934} atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit {item:277329}."] = "背包里带着火把，点击神龛顶部的{object:61934}放置余烬，然后再点击它接取下一个任务：点燃的{item:277329}。",
	["Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time."] = "经过{npc:257808}继续爬到山顶。在岩石雕像旁喝下{item:6636}，就能看到{npc:5893}（12级）：它会一直等你出手，但放置越久就越强，而且免疫火焰。立刻用{spell:8017}和{spell:8042}起手。它每次都会掉落{item:6655}。",
	["Follow the road east to the tunnel towards {area:806}. Out of the first tunnel, keep left past {npc:1959} and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to {npc:257597}' cave above the farm. He hands you the {item:6653}: keep it until the end of the chain."] = "沿路向东到通往{area:806}的隧道。出第一个隧道后，靠左经过{npc:1959}和塔楼：一条细窄的小路虽然难看清，但小地图上会显示，它盘山而上通往农场上方的{npc:257597}洞穴。他给你{item:6653}：留到任务链结束。",
	["From {npc:257597}' ledge you can drop carefully down the mountain into {zone:1432}, or walk back through the tunnel. {npc:257808} keeps the shrine on the peak just south of {area:144}: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak."] = "从{npc:257597}的岩架，你可以小心地从山上跳到{zone:1432}，或从隧道走回去。{npc:257808}守着{area:144}正南方山顶上的神龛：一条沿悬崖岩架、由石图腾标记的隐秘小路，从山顶北边的道路向上通往那里。",
	["Lost the {quest:94473}?"] = "弄丢了{quest:94473}？",
	["Only if the {quest:94473} is gone from your bags: {npc:257808} gives you another."] = "只有在{quest:94473}从你的包里消失时：{npc:257808}会再给你一个。",
	["Shaman"] = "萨满",
	["The Shrine of Eternal Flame"] = "永恒之焰神龛",
	["The Stonesplinter Seers (level 13-14) stand among the troggs of {area:923} in the south of the loch, and in the trogg camps north-east of {area:144}. They throw {spell:1245113} from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes."] = "石裂先知（13-14级）混在湖泊南部{area:923}的穴居人中，也在{area:144}东北的穴居人营地。他们会从40码外投掷{spell:1245113}，受伤时会跑去求援：一次拉一只。约5分钟刷新。",
	["The Tunnel Rat Geomancers (level 12-13) work only inside the {area:149} at the north end of the loch, past {area:144}. They cast {spell:2136} behind a {spell:134} and run for help at low health."] = "隧道鼠地卜师（12-13级）只在湖泊北端、过了{area:144}之后的{area:149}内活动。他们会躲在{spell:134}后面施放{spell:2136}，低血量时跑去求援。",
	["The {object:61934}"] = "{object:61934}",
	["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "每个火焰图腾都要用的{item:5176}，配合它使用的{spell:3599}，以及 Forever 的{item:263412}。",
	["{item:6636}, beside the statue"] = "{item:6636}，雕像旁",
	["{npc:257597}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:257597}：{spell:3599}、你的{item:5176}和{item:263412}",
	["{npc:257808}: a new {quest:94473}"] = "{npc:257808}：新的{quest:94473}",
	["{npc:258113}, {area:131}; or {npc:258098}, {zone:1455}"] = "{npc:258113}，{area:131}；或{npc:258098}，{zone:1455}",
	["{quest:94449} (Alliance)"] = "{quest:94449}（联盟）",
}

G["forever/collectibles/mounts/alliance/ram"] = {
	["Any Alliance race can buy these rams, but riding one also takes {spell:826}, which only Dwarves get with {skill:762}. {npc:4772} teaches it to other races once they are Exalted with {faction:47} (the Ironforge Reputation guide shows the way). Until then, don't buy a ram for this character."] = "任何联盟种族都能购买这些山羊，但骑乘还需要{spell:826}，只有矮人通过{skill:762}获得。{npc:4772}会在其他种族与{faction:47}达到崇拜后教授它（铁炉堡声望攻略有详细指引）。在此之前，不要为这个角色购买山羊。",
	["{area:803} is east of {area:131} on the road to {zone:1432}; {npc:4772} stands beside {npc:1261}'s rams. At 40 {npc:4772} teaches {skill:762} to Dwarves for 100g (10% less at Honored with {faction:47}), and it comes with a ram. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:803}位于{area:131}东边、通往{zone:1432}的路上；{npc:4772}站在{npc:1261}的山羊旁。40级时，{npc:4772}以100金向矮人教授{skill:762}（与{faction:47}达到尊敬时便宜10%），并附带一只山羊。其他种族可在本族的骑术训练师处学习{skill:762}，并获得自己的第一只坐骑。",
	["{spell:826} for other races"] = "其他种族需要{spell:826}",
}

