	["{item:257107}; below ground"] = "{item:257107}；在地下",
	["{item:262668}: by the formations"] = "{item:262668}：在石阵旁",
	["{item:263993}: {npc:257196} holds it, west of the shrine's approach; defeat him for it on the way in"] = "{item:263993}：由{npc:257196}持有，在神殿入口通道以西；进去的路上击败他即可获得",
	["{npc:249363} keeps watch east of the grove. The {npc:251143} and Al'Aketh Converts gather just north of her; the {object:460002} rises further north: cast your {spell:1259705} racial ability at it."] = "{npc:249363}在林地东边放哨。{npc:251143}和奥阿克皈依者聚集在她北边；{object:460002}在更北处耸立：对着它施放你的种族技能{spell:1259705}。",
	["{npc:251905}: Camping 101 asks you to learn it"] = "{npc:251905}：“露营入门”要求你学会它",
	["{npc:251918} along the way to Shen'dar turn-ins"] = "前往杉达尔交任务途中的{npc:251918}",
	["{npc:251918} on the way"] = "{npc:251918}，途中",
	["{npc:252095} camps south of the Ursera den. The Al'Aketh thugs hold the camp south-west of her; {npc:256935} stands in its middle.
Careful: {npc:256935} casts shocks; drag him clear of the other cultists before fighting so they don't join in."] = "{npc:252095}在乌尔瑟拉巢穴以南扎营。奥阿克暴徒占据她西南方的营地；{npc:256935}站在营地中央。
注意：{npc:256935}会施放震击法术；开战前把他拉离其他信徒，以免它们加入战斗。",
	["{npc:252359}, the druid trainer, stands between the west gate and Valennia's house."] = "德鲁伊训练师{npc:252359}站在西门与瓦伦妮娅的房屋之间。",
	["{npc:252359}: {quest:94006} (level 10)"] = "{npc:252359}：{quest:94006}（10级）",
	["{npc:252377}, beside {npc:257006}: {npc:257196} holds the Bulwark at the {area:16629}"] = "{npc:252377}，在{npc:257006}旁：{npc:257196}在{area:16629}持有壁垒",
	["{npc:252383}, upstairs"] = "{npc:252383}，在楼上",
	["{npc:252389} takes back the first {item:15908} and hands you two more, one at a time: Ornery Galestriders and Vuldren Alphas roam the fields just north of her. Tame each with its rod and bring the rod back to her. {npc:254411}, beside her, teaches {spell:5149}."] = "{npc:252389}收回第一根{item:15908}，再逐一交给你两根：暴躁的疾风行者和鹫龙头领就在她北边的田野上游荡。用对应的驯兽棒驯服每只，再把驯兽棒带回给她。她旁边的{npc:254411}教授{spell:5149}。",
	["{npc:252389}, beside {npc:257006}: the first {item:15908}"] = "{npc:252389}，在{npc:257006}旁：第一根{item:15908}",
	["{npc:252475} sends you on to {area:279}. Once you have trained, take the skycutter from the dock tower just south of {area:16638}: it lands by the Kirin Tor camp west of {area:279}, beside {npc:259084} and the Skyborne Portal."] = "{npc:252475}派你前往{area:279}。训练完成后，从{area:16638}正南的码头塔乘飞空艇：它会降落在{area:279}以西的肯瑞托营地旁，就在{npc:259084}和天裔传送门旁。",
	["{npc:252476}, upstairs"] = "{npc:252476}，在楼上",
	["{npc:253590}, in the sanctum; upstairs"] = "{npc:253590}，在内殿；在楼上",
	["{npc:254588}, among the crabs: tame one with {npc:252389}'s first {item:15908} while you are there"] = "{npc:254588}，在螃蟹群中：你在那里时用{npc:252389}的第一根{item:15908}驯服一只",
	["{npc:255853}, by the falls north-east of {area:16638}, on the way north: {spell:5487}"] = "{npc:255853}，在{area:16638}东北的瀑布旁，位于向北的路上：{spell:5487}",
	["{npc:257006} and {npc:252448} stand on {area:16638}'s west side, beside the inn; {npc:252377} and {npc:252389} train just west of {npc:257006}. Windsong Crawlers line the shore further west, around 51,70."] = "{npc:257006}和{npc:252448}站在{area:16638}西侧、旅店旁；{npc:252377}和{npc:252389}在{npc:257006}正西训练。再往西的海岸一线是风歌爬行者，坐标约51,70。",
	["{npc:257006}, inside"] = "{npc:257006}，室内",
	["{npc:257065} waits at the entrance to {quest:92529}, south of Shen'dar. The {spell:1254832} lets you walk in among the faithful."] = "{npc:257065}在杉达尔以南{quest:92529}的入口等候。{spell:1254832}能让你走进信徒中间。",
	["{npc:257532} on the way"] = "{npc:257532}，途中",
	["{npc:258098} in {zone:1455}; {area:16624} has no shaman trainer"] = "{npc:258098}在{zone:1455}；{area:16624}没有萨满祭司训练师",
	["{npc:258098} in {zone:1455}; {area:16638} has no shaman trainer"] = "{npc:258098}在{zone:1455}；{area:16638}没有萨满祭司训练师",
	["{npc:259084} stands beside the Skyborne Portal, where the skycutter lands by the Kirin Tor camp west of {area:279}. The portal takes you to {zone:1453}."] = "{npc:259084}站在天裔传送门旁，飞空艇就降落在{area:279}以西的肯瑞托营地边。传送门会把你送往{zone:1453}。",
	["{npc:259084}, inside"] = "{npc:259084}，在里面",
	["{npc:5141} in {zone:1455}; {area:16638} has no priest trainer"] = "{npc:5141}在{zone:1455}；{area:16638}没有牧师训练师",
	["{npc:5148} in {zone:1455}; {area:16624} has no paladin trainer"] = "{npc:5148}在{zone:1455}；{area:16624}没有圣骑士训练师",
	["{npc:5148} in {zone:1455}; {area:16638} has no paladin trainer"] = "{npc:5148}在{zone:1455}；{area:16638}没有圣骑士训练师",
	["{npc:5504}, {zone:1453}'s druid trainer, teaches you {spell:18960}. {npc:11802}'s welcome waits for your {spell:499} trip at the end of {zone:1439}."] = "{zone:1453}的德鲁伊训练师{npc:5504}教你{spell:18960}。{npc:11802}的欢迎在{zone:1439}尽头等着你的{spell:499}之旅。",
	["{object:631299}, inside"] = "{object:631299}，在里面",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
}

G["forever/class/priest/divine-grace-and-feedback"] = {
	["A Human priest in {zone:1438} at 10: {npc:3600}, in the building at the north edge of {area:186}, hands you a letter for {npc:376} in {zone:1453}."] = "人类牧师10级时在{zone:1438}：{area:186}北缘建筑里的{npc:3600}会给你一封写给{zone:1453}的{npc:376}的信。",
	["Any {quest:94776} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "任何{quest:94776}信都交给光明大教堂祭坛的{npc:376}。",
	["Any {quest:94777} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "任何{quest:94777}信都交给光明大教堂祭坛的{npc:376}。",
	["Any {quest:94778} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "任何{quest:94778}信都交给光明大教堂祭坛的{npc:376}。",
	["Any {quest:94779} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "任何{quest:94779}信都交给光明大教堂祭坛的{npc:376}。",
	["At 10, go to {npc:376} at the altar of the Cathedral of Light, in {zone:1453}'s {object:2098}, and take her quest: she teaches {quest:94773} on the spot. No letter needed; one from another trainer works too (next steps). {quest:94773} instantly heals a friend below half health and clears {spell:6788}, so you can shield them again (5-minute cooldown); it does not work on yourself. Human priests do not get Desperate Prayer in Forever: this is their spell instead."] = "10级时去找光明大教堂祭坛的{npc:376}，就在{zone:1453}的{object:2098}里，接下她的任务：她会当场教你{quest:94773}。无需信件；别的训练师给的信同样可以（见后续步骤）。{quest:94773}立刻治疗生命值低于一半的队友并清除{spell:6788}，让你能再次为他上盾（冷却5分钟）；对自己无效。人类牧师在Forever中不会获得绝望祈祷：取而代之的就是这个法术。",
	["At 10, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a letter for {npc:376}. {area:87} is on the road north to {zone:1453}, so it costs no detour."] = "10级时，{area:87}狮王之傲旅店楼上的{npc:377}会给你一封写给{npc:376}的信。{area:87}就在向北通往{zone:1453}的大路旁，不会绕路。",
	["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you a letter for {npc:376} in {zone:1453}. The {area:2257} from {object:171524} takes you there."] = "20级时在{zone:1455}，{object:32386}（{object:32362}）里的{npc:11406}会给你一封写给{zone:1453}的{npc:376}的信。从{object:171524}乘{area:2257}即可到达。",
	["At 20 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a letter for {npc:376} in {zone:1453}."] = "20级时在{zone:1457}，月神殿上层露台{npc:7999}旁的{npc:11401}会给你一封写给{zone:1453}的{npc:376}的信。",
	["At 20, {npc:376} at the altar of the Cathedral of Light teaches {spell:13896} with a quest she gives and takes back at once."] = "20级时，光明大教堂祭坛的{npc:376}会用一个她给出后立刻收回的任务教你{spell:13896}。",
	["Hand Alathea's letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (from {zone:1457}: the portal down to {area:702}, the boat to {area:442}, then the boat to {area:17203}): she teaches {spell:13896}."] = "把阿拉希亚的信交给{zone:1453}光明大教堂祭坛的{npc:376}（从{zone:1457}出发：乘传送门下去到{area:702}，坐船到{area:442}，再坐船到{area:17203}）：她教你{spell:13896}。",
	["Hand Josetta's letter to {npc:376} at the altar of the Cathedral of Light: she teaches {quest:94774}."] = "把乔塞塔的信交给光明大教堂祭坛的{npc:376}：她教你{quest:94774}。",
	["Hand Rohan's letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (the {area:2257} from {object:171524} in {zone:1455}): she teaches {spell:13896}."] = "把罗翰的信交给{zone:1453}光明大教堂祭坛的{npc:376}（在{zone:1455}从{object:171524}乘{area:2257}）：她教你{spell:13896}。",
	["Hand {npc:3600}'s letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (from {zone:1438}: the boat from {area:702} to {area:442}, then the boat to {area:17203}): she teaches {quest:94775}."] = "把{npc:3600}的信交给{zone:1453}光明大教堂祭坛的{npc:376}（从{zone:1438}出发：从{area:702}坐船到{area:442}，再坐船到{area:17203}）：她教你{quest:94775}。",
	["Priest"] = "牧师",
	["The Human priest spells: {quest:94773} at 10 (new in Forever), {spell:13896} at 20. Free, no objectives."] = "人类牧师法术：10级学{quest:94773}（Forever新增），20级学{spell:13896}。免费，无任务目标。",
	["{npc:11401}: take her {quest:5676} letter"] = "{npc:11401}：拿她的{quest:5676}信",
	["{npc:11406}: take his {quest:5676} letter"] = "{npc:11406}：拿他的{quest:5676}信",
	["{npc:3600}: take her {quest:94773} letter"] = "{npc:3600}：拿她的{quest:94773}信",
	["{npc:377}: take her {quest:94773} letter"] = "{npc:377}：拿她的{quest:94773}信",
	["{quest:94774}: Josetta's letter"] = "{quest:94774}：乔塞塔的信",
	["{quest:94775}: {npc:3600}'s letter"] = "{quest:94775}：{npc:3600}的信",
	["{quest:94776}: a letter from another trainer"] = "{quest:94776}：另一个训练师的信",
	["{quest:94777}: a letter from another trainer"] = "{quest:94777}：另一个训练师的信",
	["{quest:94778}: a letter from another trainer"] = "{quest:94778}：另一个训练师的信",
	["{quest:94779}: a letter from another trainer"] = "{quest:94779}：另一个训练师的信",
	["{spell:13896}: Alathea's letter"] = "{spell:13896}：阿拉希亚的信",
	["{spell:13896}: Rohan's letter"] = "{spell:13896}：罗翰的信",
}

G["forever/class/priest/starshards-and-elunes-grace"] = {
	["At 10 in {zone:1426}, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "10级时在{zone:1426}，{area:131}中{area:2102}里的牧师训练师{npc:1226}会给你{quest:5628}，一封写给{zone:1457}的{npc:11401}的信。",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "10级时在{zone:1429}，{area:87}狮王之傲旅店楼上的{npc:377}会给你{quest:5628}，一封写给{zone:1457}的{npc:11401}的信。",
	["At 10 in {zone:1453}, {npc:5489} at the altar of the Cathedral of Light hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "10级时在{zone:1453}，光明大教堂祭坛旁的{npc:5489}会给你{quest:5628}，一封写给{zone:1457}的{npc:11401}的信。公园里的{npc:11397}也有同样的信。",
	["At 10 in {zone:1455}, {npc:5142} in the {object:32386} ({object:32362}) hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "10级时在{zone:1455}，{object:32386}（{object:32362}）里的{npc:5142}会给你{quest:5628}，一封写给{zone:1457}的{npc:11401}的信。",
	["At 10, go to {npc:11401} on the upper balcony of the Temple of the Moon, at the south end of {zone:1457}: take the ramp up from the temple floor; she stands beside {npc:7999}. {quest:5627} is given and taken back at once and teaches {spell:10797}. No letter needed. Forever made {spell:10797} hit much harder, on a 30-second cooldown."] = "10级时去找{npc:11401}，她在{zone:1457}南端月神殿的上层露台：从神殿地面沿坡道上去；她站在{npc:7999}旁边。{quest:5627}给出后立刻收回，教你{spell:10797}。无需信件。Forever让{spell:10797}伤害大幅提高，冷却30秒。",
	["At 10, {npc:3600}, the priest trainer in the building at the north edge of {area:186}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {area:186} is on the road west to {zone:1457}."] = "10级时，{area:186}北缘建筑里的牧师训练师{npc:3600}会给你{quest:5628}，一封写给{zone:1457}的{npc:11401}的信。{area:186}就在向西通往{zone:1457}的大路旁。",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you an {spell:2651} letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "20级时在{zone:1453}，光明大教堂祭坛旁的{npc:376}会给你一封{spell:2651}信，写给{zone:1457}的{npc:11401}。公园里的{npc:11397}也有同样的信。",
	["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you an {spell:2651} letter for {npc:11401} in {zone:1457}."] = "20级时在{zone:1455}，{object:32386}（{object:32362}）里的{npc:11406}会给你一封{spell:2651}信，写给{zone:1457}的{npc:11401}。",
	["At 20, {npc:11401} on the upper balcony of the Temple of the Moon, beside {npc:7999}, teaches {quest:5672} with a quest she gives and takes back at once. In Forever, {quest:5672} halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss."] = "20级时，月神殿上层露台{npc:7999}旁的{npc:11401}用一个她给出后立刻收回的任务教你{quest:5672}。在Forever中，{quest:5672}使近战和远程攻击命中你的几率减半，持续15秒或直到三次攻击未命中。",
	["Hand Laurena's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "把劳伦娜的信交给{npc:11401}，她在{zone:1457}月神殿的上层露台、{npc:7999}旁边：从{area:17203}（或{area:150}）坐船到{area:442}，再坐船到{area:702}，然后乘传送门上去进入{zone:1457}。",
	["Hand Nara's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "把娜拉的信交给{npc:11401}，她在{zone:1457}月神殿的上层露台、{npc:7999}旁边：从{area:17203}（或{area:150}）坐船到{area:442}，再坐船到{area:702}，然后乘传送门上去进入{zone:1457}。",
	["Hand Rohan's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "把罗翰的信交给{npc:11401}，她在{zone:1457}月神殿的上层露台、{npc:7999}旁边：从{area:17203}（或{area:150}）坐船到{area:442}，再坐船到{area:702}，然后乘传送门上去进入{zone:1457}。",
	["Priest"] = "牧师",
	["Take the road west from {area:186} into {zone:1457} and go up to the upper balcony of the Temple of the Moon, beside {npc:7999}: {npc:11401} takes {quest:5629} and teaches {spell:10797}."] = "从{area:186}沿路向西进入{zone:1457}，上到月神殿上层露台、{npc:7999}旁边：{npc:11401}收下{quest:5629}并教你{spell:10797}。",
	["The Night Elf priest spells: {spell:10797} at 10, {spell:2651} at 20. Free, no objectives."] = "暗夜精灵牧师法术：10级学{spell:10797}，20级学{spell:2651}。免费，无任务目标。",
	["{npc:11406}: take his {spell:2651} letter"] = "{npc:11406}：拿他的{spell:2651}信",
