G["forever/class/rogue/blade-of-cunning-alliance"] = {
	["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "10级时，{area:186}旅店里的盗贼训练师{npc:3599}会给你一朵玫瑰，送给{zone:1457}的{npc:4163}。如果玫瑰丢了，放弃任务重新接。",
	["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "10级时，{area:87}狮王之傲旅店楼上的盗贼训练师{npc:917}会给你一个包裹，送给{zone:1453}的{npc:332}。如果还没学{spell:921}就先学：这条任务链需要它。",
	["Head north to {zone:1453}. Shaw stands upstairs in the SI:7 building in {object:2100} (the quest says the Barracks; it means SI:7)."] = "向北前往{zone:1453}。肖尔站在{object:2100}军情七处大楼的楼上（任务里说是兵营，其实指军情七处）。",
	["Head west to {area:133}. Beside the road to its entrance stands a wooden spiral tower: {npc:6886} waits stealthed on the top platform, next to a level 10 {npc:1211}, so you only see him up close."] = "向西前往{area:133}。通往入口的路边立着一座木制螺旋塔：{npc:6886}潜行等在顶层平台上，旁边有一只10级的{npc:1211}，所以只有靠近才能看见他。",
	["Head west to {zone:1457}. {npc:4163} is below ground in the {area:1658}: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground."] = "向西前往{zone:1457}。{npc:4163}在{area:1658}的地下：下去的路口在大德鲁伊树左侧那棵分叉树脚下，靠近夜刃豹训练师。她的地图标记显示在地面以上。",
	["Rogue"] = "潜行者",
	["The {npc:6846} (level 10, a goblin) works in the dock house at {area:797}, on the river at Elwynn's southern edge, south of {area:87}. Stealth in and {spell:921} him from behind: the schedule never drops from his corpse. Do not open with {spell:2070} or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death."] = "{npc:6846}（10级，地精）在{area:797}的码头小屋干活，那里是艾尔文森林南缘的河边，{area:87}以南。潜行进去从背后{spell:921}他：日程表永远不会从他尸体上掉落。不要用{spell:2070}起手，也别直接开打：他会叫来三波保镖。避开屋里的壁炉，它们会把你烧出潜行。他死亡后2到5分钟刷新。",
	["{item:7675}: {spell:921} the {npc:6846}"] = "{item:7675}：对{npc:6846}使用{spell:921}",
	["{item:7737}: Pick Pocket Sethir the Ancient"] = "{item:7737}：偷窃上古者塞希尔",
	["{npc:5165} is in the {object:32383}, the rogue quarter in the north of {zone:1455}: go into the building with a shady dealer outside and down the stairs."] = "{npc:5165}在{object:32383}，即{zone:1455}北部的盗贼区：走进门外有个鬼祟商人的那栋建筑，下楼。",
	["{npc:6909} (level 12 satyr) lives out on a great branch north of the {area:264}: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then {spell:2983} away. He is back 8 1/2 minutes after a death."] = "{npc:6909}（12级萨特）住在{area:264}以北的一根巨枝上：从林地北面墙上的V形缺口穿过去，沿巨枝向外走。偷他的口袋拿日志；杀他不会掉落，而且开打会引出三个塞希尔的爪牙。他在主枝和侧枝之间走动：潜行在主枝尽头等候，等他回来时从背后偷。然后用{spell:2983}脱身。他死亡后8分半钟刷新。",
}

G["forever/class/warrior/fire-hardened-armor"] = {
	["A hauberk at 28, a coif, leggings and gauntlets from three smiths, and a shield on the way."] = "28级拿锁甲上衣，三位铁匠分别给头巾、护腿和护手，途中还有一面盾。",
	["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "20级时，{object:2100}战士训练师建筑里{npc:5480}身旁的{npc:5479}派你去赤脊山找{quest:1698}。",
	["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "回{object:28027}找{npc:5413}领锁甲上衣。然后他会派你去找本种族的铁匠；另外两位铁匠的部件你也可以做：直接找他们谈。",
	["Ride the {area:2257} from {zone:1453} to {zone:1455}. {quest:1704}, a gnome smith, works in {object:171524} near the engineering trainers. He wants 20 {item:6848}."] = "从{zone:1453}乘{area:2257}到{zone:1455}。侏儒铁匠{quest:1704}在{object:171524}工程训练师附近干活。他要20个{item:6848}。",
	["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, and his guards come with him. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "鲁古格是{zone:1413}南端地下城{area:1717}里的精英野猪人（28级）；这是五人地下城：需要五人小队，他的卫兵会跟他一起来。进去后在第一个岔路走左边，穿过树根桥，经过那个空的大锅：他在右侧的死路里，路上约有十个精英。他会施放{spell:403}并召唤大地轰响者。药瓶必掉。",
	["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five. {npc:6170} (level 32, not elite) carries the {item:6845} (also four in five): he walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. {npc:6170} and the Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "{zone:1431}的夜祸狼人（黑暗奔跑者、邪牙、织影者、狼人和腐化者，26-31级）在{area:42}以南和以西活动，五次击杀有四次掉落{quest:1705}。{npc:6170}（32级，非精英）携带{item:6845}（同样是五次四次）：他在{area:42}东南的{area:2161}矿洞内口与洞口之间走动，所以在入口等着，把他拉到外面打。{npc:6170}和腐化者会下毒和嚎叫；邪牙会造成{spell:3427}。",
	["The chimaeras live south-west of {area:460} in the {area:465}: you need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "奇美拉住在{area:460}西南的{area:465}：你需要12根烧焦的角，来自幼年奇美拉（25-27级）和青年奇美拉（23-25级），五次四次掉落；还要从{npc:6167}（28级，那只大的）拿{item:6840}，同样五次四次。那里只有三只幼年、两只青年和一只族长，各5分钟刷新，所以要做好等待的准备。幼年和族长会喷{spell:3396}，青年会施放{spell:403}。联盟：飞到{area:467}后向南。",
	["The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once."] = "贝壳躺在{area:482}风蛇巢下方的地上，位于{zone:1441}西部、峡谷更深处。那里只有九个，每个采集后3分钟刷新，所以你会等上一阵；有些像贝壳的东西无法拾取。高崖风蛇（28-31级）守护着它们，有时会几只一起过来。",
	["The {quest:1708} grows on the sea floor just south of {area:150}, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and an {item:5996} removes the risk."] = "{quest:1708}生长在{area:150}正南的海底，鱼人小屋和一条破船旁：那里有八株，港口东南有两株，各3分钟刷新，所以要等刷新凑够20个。鱼人在水下会用网困住你：留意呼吸条，一瓶{item:5996}就能消除风险。",
	["Warrior"] = "战士",
	["You have one hour, and {npc:6166}'s {spell:8553} leaves you drunk for 8-10 minutes. Run north-west into the {area:98}, keeping close to the cliff wall to miss most gnoll packs, and go in as far as the first fork; then come back to {npc:6166} (from the ridge you can jump down into {area:69}). Dying and releasing your spirit fails the quest: abandon it and {npc:6166} gives it again."] = "你有一个小时，而{npc:6166}的{spell:8553}会让你醉酒8-10分钟。向西北跑进{area:98}，贴着崖壁走以避开大多数豺狼人群，一直进入到第一个岔路；然后回到{npc:6166}（从山脊上可以直接跳进{area:69}）。死亡并释放灵魂会导致任务失败：放弃任务，{npc:6166}会再给你一次。",
	["You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the {zone:1437}, north of {area:836}; every one drops a fang. They poison; back in 5 minutes."] = "你需要50颗牙。吸血潜伏者和洞穴潜伏者（21-22级）爬行在{zone:1437}中部、{area:836}以北；每只都掉一颗牙。它们会下毒；5分钟刷新。",
	["{item:6839}, from the young chimaeras"] = "{item:6839}，来自青年奇美拉",
	["{item:6840}, from the {npc:6167}"] = "{item:6840}，来自{npc:6167}",
	["{item:6845}, from {npc:6170}"] = "{item:6845}，来自{npc:6170}",
	["{item:6848}, from {quest:1708}"] = "{item:6848}，来自{quest:1708}",
	["{npc:1416} keeps the weapon shop in the north-west of the {object:28027}, a short walk from {npc:5413}. He wants 20 {quest:1705} and the {item:6845}."] = "{npc:1416}在{object:28027}西北角经营武器店，离{npc:5413}只几步路。他要20个{quest:1705}和{item:6845}。",
	["{npc:5413} works in the Dwarven District of Stormwind. He takes the {item:6843} (lost it? abandon the quest and {npc:6166} gives a new one) and gives you {item:6970}, a shield; {quest:1701} is a level 28 quest, with {item:6842} listing what it needs."] = "{npc:5413}在暴风城矮人区干活。他收下{item:6843}（弄丢了？放弃任务，{npc:6166}会给一个新的）并给你{item:6970}，一面盾；{quest:1701}是28级任务，{item:6842}里列着所需材料。",
	["{quest:1698} sits in the inn at {area:69}. His test is timed: before you take it, clear the Redridge gnolls on the path to the {area:98} in the hills north-west of {area:69}, including the two on the rock by the cave mouth (climb it from its right side)."] = "{quest:1698}待在{area:69}的旅店里。他的考验限时：接任务前，先清掉{area:69}西北丘陵中通往{area:98}路上的赤脊豺狼人，包括洞口岩石上的那两只（从岩石右侧爬上去）。",
	["{quest:1703} works on the south side of the {area:1660} in {zone:1457}. He wants 20 {quest:1710}."] = "{quest:1703}在{zone:1457}的{area:1660}南侧干活。他要20个{quest:1710}。",
	["{quest:1705}, from the Nightbane worgen"] = "{quest:1705}，来自夜祸狼人",
}

G["forever/collectibles/mounts/alliance/black-war-mounts"] = {
	["{item:18243}, {spell:10907}, 100g"] = "{item:18243}，{spell:10907}，100金",
	["{item:18244}, {spell:826}, 100g"] = "{item:18244}，{spell:826}，100金",
	["{npc:12783} sells the mounts in {zone:1453}'s {object:2100} by the {area:2918}, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Humans ride the steed, Night Elves the tiger, Gnomes the battlestrider, Dwarves the ram. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city)."] = "{npc:12783}在{zone:1453}的{object:2100}里、{area:2918}旁出售坐骑，就在其他荣誉军需官旁边。Forever客户端标价每种100金。每种还都需要对应种族的骑术：人类骑战马，暗夜精灵骑虎，侏儒骑机械陆行鸟，矮人骑山羊。天裔或任何选择其他种族坐骑的人，须先在该种族训练师处学会对应骑术（需该种族主城崇拜）。",
	["{npc:14332}, {spell:824}, 100g"] = "{npc:14332}，{spell:824}，100金",
	["{spell:1299382} come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; Commander (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. {skill:762} one at full speed needs Journeyman {skill:762} (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman {skill:762}."] = "{spell:1299382}来自战场、PvP任务和赛季每周任务，每周有上限；达到指挥官（军衔11级）可解锁黑色战争坐骑。角色面板的“玩家对玩家”标签页显示你的军衔和可购买物品。全速骑乘需要{skill:762}，而且必须学会中级{skill:762}（60级）。Polestar读不到你的军衔，所以这一步要等到60级且学会中级{skill:762}。",
	["{spell:22723}, {spell:828}, 100g"] = "{spell:22723}，{spell:828}，100金",
}

G["forever/collectibles/mounts/alliance/stormpike-battle-charger"] = {
	["The Forever client lists it at 200g and level 60. It runs at full speed, so riding it needs Journeyman {skill:762}; any Alliance race can ride it."] = "Forever客户端标价200金、60级。它以全速奔跑，因此骑乘需要中级{skill:762}；任何联盟种族都可骑乘。",
	["{area:2839} (level 51+) raises {faction:730}: win, capture towers and graveyards, and hand in the battleground's turn-ins; the Alterac Valley Reputation guide shows the fastest way. {npc:13217} waits outside the battleground on the {zone:1416} border above {area:287}; {npc:13216} inside {area:2839} sells the same mount."] = "{area:2839}（51级以上）提升{faction:730}：获胜、占领塔和墓地、交战场任务物品；奥特兰克山谷声望指南有最快路线。{npc:13217}在战场外{zone:1416}边界、{area:287}上方等候；{area:2839}内的{npc:13216}出售同样的坐骑。",
}

G["forever/collectibles/mounts/alliance/swift-saber"] = {
	["Any Alliance race can buy these sabers, but riding one also takes {spell:828}, which only Night Elves get with {skill:762}. {npc:4753} teaches it to other races once they are Exalted with {faction:69} (the Darnassus Reputation guide shows the way). Until then, don't buy a saber for this character."] = "任何联盟种族都能买这些夜刃豹，但骑乘还需{spell:828}，只有暗夜精灵随{skill:762}获得。其他种族在{faction:69}达到崇拜后，{npc:4753}会教它（达纳苏斯声望指南有路线）。在此之前，别为这个角色买夜刃豹。",
	["{npc:4753} and {npc:4730}'s sabers are in the {area:1658}'s riding grounds in {faction:69}. At 60 {npc:4753} teaches Journeyman {skill:762} to Night Elves for 1,000g (10% less at Honored with {faction:69}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift saber costs 200g here."] = "{npc:4753}和{npc:4730}的夜刃豹在{faction:69}的{area:1658}骑术训练场。60级时{npc:4753}以1,000金教暗夜精灵中级{skill:762}（{faction:69}尊敬时便宜10%）；暴雪称会附赠坐骑。其他种族在本族骑术训练师处学习。此处每只迅捷夜刃豹200金。",
	["{spell:828} for other races"] = "其他种族的{spell:828}",
}

