G["forever/alliance/dwarf/01-dun-morogh"] = {
	["Back east through {area:131}: the class quests here wait for level 10."] = "向东返回，穿过{area:131}：这里的职业任务要等到10级。",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {area:40} is next, west of {area:87}."] = "回到{npc:6122}。在{object:2164}地窖里的召唤法阵上使用{item:6928}，击败它召唤出的虚空行者。接下来去{area:40}，在{area:87}西边。",
	["Bartleby"] = "巴特莱比",
	["Below ground"] = "地下",
	["Burly Rockjaw Trogg"] = "强壮的石颚穴居人",
	["Class trainer"] = "职业训练师",
	["Dark Iron Spy"] = "黑铁间谍",
	["Druid trainer"] = "德鲁伊训练师",
	["Elder Crag Boar"] = "老峭壁野猪",
	["Flintfire's shipments lie on the cave floor, and {object:460004} is missing somewhere inside.
Careful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "燧火的货物散落在洞穴地面，{object:460004}则在洞穴某处遗失。
小心：洞穴里的雪怪站得很近，战斗很容易同时引到好几只；在洞外用远程攻击一只一只引出来就能避免。",
	["Follow the road all the way east to the {area:806} at the {area:38} tunnel."] = "沿路一直向东，到{area:38}隧道处的{area:806}。",
	["Follow the road north-east from {area:131} to the depot: the whole east of {area:1} is one sweep from here."] = "从{area:131}沿路向东北前往补给站：{area:1}整个东边都可以从这里一次清完。",
	["Follow the road through the tunnel and north-east to {area:131}. Start outside: {npc:1252} and Eric's campfire are in front of the {area:2102}."] = "沿路穿过隧道，向东北到{area:131}。从外面开始：{npc:1252}和埃里克的营火在{area:2102}前面。",
	["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, {npc:6179} and {npc:6178} on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "沿路走到{zone:1455}，乘坐{object:32362}：{npc:5149}、{npc:6179}和{npc:6178}在{object:32386}里，{npc:6179}和{npc:6178}在它的上层：上楼的楼梯就在{npc:5149}东北。乞丐{npc:6175}在城中游荡。他要十块{item:2589}：{area:1}的穴居人和巨魔会掉落，拍卖行也有卖。",
	["Frostmane Headhunter"] = "霜鬃猎头者",
	["Frostmane Troll Whelp"] = "霜鬃巨魔幼崽",
	["Go through the tunnel into {area:38}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "穿过隧道进入{area:38}。刚过隧道，一条用石头标记的小路沿着通往{npc:257808}营地的北路右侧爬上山。",
	["Head back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "离开{zone:1455}往回走，沿路向东到{area:212}。{npc:6177}死在岸边：对他使用{item:6866}。在湖边潜行的黑铁间谍身上带着那份名册。",
	["Ice Claw Bear"] = "冰爪熊",
	["If you skipped {quest:314}, grind here to level 11.6 to stay on the route's plan."] = "如果你跳过了{quest:314}，就在这里刷到11.6级，以符合路线规划。",
	["Inn and flight master"] = "旅店与飞行管理员",
	["Instead of walking back up to {area:1537}, go east through the South Gate tunnel into {area:38} and follow the road north to {area:144}. {npc:1681} stands on the east side of town, past the {area:2101}; his errand pays for a flight back to {area:1537}."] = "不必走回{area:1537}，改为向东穿过南门隧道进入{area:38}，沿路向北到{area:144}。{npc:1681}在小镇东侧、{area:2101}再往前；他的差事报酬足够坐飞机回{area:1537}。",
	["Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. Back in the distillery: {npc:1699} teaches {skill:185}, then the ribs go to {npc:1267}."] = "路上杀峭壁野猪：它们的肋排在接到{npc:1267}的任务前就会掉落，并且算作任务进度。回到酿酒厂：{npc:1699}传授{skill:185}，然后把肋排交给{npc:1267}。",
	["Large Crag Boar"] = "大型峭壁野猪",
	["Level 11.6"] = "11.6级",
	["Minor Ice Elemental"] = "小型冰元素",
	["On the road back west to {zone:1455}."] = "在回西边{zone:1455}的路上。",
	["On the way"] = "顺路",
	["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Rockjaw Bonesnappers prowl the quarry and the lake; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "{area:212}旁、采石场以北的石颚伏击者，以及更东边的石颚碎背者掉落{quest:95214}。石颚碎骨者在采石场和湖边徘徊；黑铁间谍在湖岸潜行。其中一个间谍掉落{item:274268}。",
	["Rockjaw Bonesnapper"] = "石颚碎骨者",
	["Rockjaw Skullthumper"] = "石颚碎颅者",
	["Rockjaw Trogg"] = "石颚穴居人",
	["Small Crag Boar"] = "小型峭壁野猪",
	["Snow Leopard"] = "雪豹",
	["Snow Leopard Prowler"] = "雪豹潜行者",
	["The quarry lies just east of Farsen's ridge."] = "采石场就在法森山脊以东。",
	["The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for {quest:99160}.
Finish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short."] = "三支步枪在营地旁冰湖周围的雪地里。小型冰元素在湖边和路上飘荡：为{quest:99160}一路杀过去。
如果数量还不够，把营地西边小湖周围的小型冰元素也清掉。",
	["The {item:2676} grows in baskets up on {area:802}, the snowy slope north of the road between {area:131} and Brewnall: climb from the road west of {area:131}. The Frostmane Seers camped on the ridge drop it too."] = "{item:2676}长在{area:802}上的篮子里，那是{area:131}与布伦诺尔之间道路以北的雪坡：从{area:131}西边的路上山。山脊上扎营的霜鬃先知也会掉落。",
	["The {object:176785} sits next to {npc:271546}, south of the {area:136}."] = "{object:176785}在{npc:271546}旁边，{area:136}以南。",
	["The {object:270} in the distillery; below ground"] = "{object:270}在酿酒厂里；地下",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1388} is a level 12 elite: most classes solo it at level 14, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人一起做。{npc:1388}是12级精英：大多数职业在14级可以单挑，但你可能需要帮助。如果你独自一人就跳过：路线会让你把经验刷回来。",
	["Tram to {zone:1453}"] = "乘地铁前往{zone:1453}",
	["Upstairs"] = "楼上",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "趁在这里：向{npc:11867}学习法杖（{object:2096}，10银）；猎人的近战武器主要看属性，双手武器加成最多。",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "趁在这里：向{npc:11867}学习法杖（{object:2096}，10银）；升级过程中法杖的法术属性比单手武器多。",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "趁在这里：向{npc:11867}学习剑（{object:2096}，10银）；主手拿剑能让盗贼稳定升级。",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "趁在这里：向{npc:11865}学习{spell:197}（{object:32359}，10银）；双手武器让圣骑士升级最快。",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11865}学习{spell:197}（{object:32359}，10银）；双手武器让战士升级最快。",
	["While you're here: learn {spell:199} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11865}学习{spell:199}（{object:32359}，10银）；双手武器让战士升级最快。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让圣骑士升级最快。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让战士升级最快。",
	["grind on {npc:260157}"] = "刷{npc:260157}",
