G["forever/class/rogue/certificate-of-thievery"] = {
	["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165} in {zone:1455}'s {object:32383}."] = "16级时，{area:131}的{area:2102}里的{npc:1234}会让你去找{zone:1455}的{object:32383}中的{npc:5165}。",
	["At 16 {npc:3599} in the {area:186} inn sends you to {quest:2259} in {zone:1457}."] = "16级时，{area:186}旅店里的{npc:3599}会让你去{zone:1457}接{quest:2259}。",
	["At 16 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}. Taking it shuts out the other towns' breadcrumbs."] = "16级时，{area:87}狮王之傲旅店楼上那个盗贼训练师{npc:917}会让你去找{zone:1453}的{npc:6946}。接了它，其他城镇的引路任务就不会出现。",
	["Head east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} stands on a crate on one of the {area:69} docks, south of town; he gives you {item:5060} with the job ({npc:3090} in {area:69} sells more). {spell:1804} does not work without the tools in your bags."] = "向东穿过{zone:1429}进入赤脊山，或飞往{area:69}。{npc:6966}站在{area:69}某处码头的一个木箱上，在小镇南边；他会给你{item:5060}和任务（{area:69}的{npc:3090}还有更多卖）。背包里没有工具时{spell:1804}无法使用。",
	["Rogue"] = "盗贼",
	["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}."] = "16级时你的第一个开锁活儿：在{quest:2282}开{npc:6966}的锁箱，为的是{quest:2300}。",
	["{npc:4214} stands in the {area:1658}. Then the boat from {area:702} to {area:442}, and the boat from {area:442} to {area:17203}."] = "{npc:4214}站在{area:1658}。然后从{area:702}乘船到{area:442}，再从{area:442}乘船到{area:17203}。",
	["{npc:5165} is in the house with a shady dealer outside, in the {object:32383}, down the stairs. Then fly or take the {area:2257} to {zone:1453}."] = "{npc:5165}在门口有可疑商人的那间房子里，位于{object:32383}，沿楼梯下去。然后飞往或乘{area:2257}到{zone:1453}。",
	["{npc:6946} stands upstairs in the {quest:2300} building in {object:2100}, behind the rogue trainers. Before you leave: if you lack {spell:1804}, {npc:13283} in the {quest:2300} building teaches it; Lockpicking is the test of the next quest."] = "{npc:6946}站在{object:2100}的{quest:2300}建筑楼上，在盗贼训练师身后。离开前：如果你没有{spell:1804}，{quest:2300}建筑里的{npc:13283}会教你；开锁是下一个任务的考核内容。",
	["{quest:2282} stands east of {area:69}, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until {object:121264} opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75."] = "{quest:2282}位于{area:69}以东、路边的高处；黑石兽人在附近游荡。里面的练习锁箱几乎立刻刷新：反复开锁，直到{object:121264}为你打开（约25点开锁技能）。你的开锁上限每级提升5点，所以等级低时可能卡住。有些箱子带陷阱（比如冰冻陷阱）；技能照样会涨。在Forever服务器，20级的蜘蛛会在箱子附近游荡：先清掉它们，或者带上朋友。锁箱里始终放着信物，使用后两秒就回来。在还能涨技能时继续练：下一个职业任务需要约75点。",
}

G["forever/class/warlock/voidwalker-alliance"] = {
	["At 10 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257} from {object:171524}. If {npc:6120} does not offer it, go to {npc:6122} anyway: he still gives you the next quest."] = "10级时，{zone:1455}的{object:32383}里的术士训练师{npc:6120}会让你去找{zone:1453}的{npc:6122}。从{object:171524}乘{area:2257}过去。如果{npc:6120}没有给你任务，也直接去找{npc:6122}：他照样会给你下一个任务。",
	["At 10 {npc:6121}, in the cellar of the Lion's Pride Inn in {area:87} (the stairs down are in the back room past the butcher's table), sends you to {npc:6122} in {zone:1453}."] = "10级时，{area:87}狮王之傲旅店地窖里的{npc:6121}（下去的楼梯在里屋、经过屠夫的桌子）会让你去找{zone:1453}的{npc:6122}。",
	["Back to {npc:6122}. He hands you the {item:6928}. The circle is hard to find: take the stairs behind {npc:6122} down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: {spell:14868}, Corruption and {spell:348} with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: {npc:6122} takes it back."] = "回到{npc:6122}。他把{item:6928}交给你。法阵很难找：走{npc:6122}身后的楼梯下去；走到最底层走廊的中段，左侧有一条侧梯通向一个中间有发光紫色法阵的房间。站在法阵上使用项圈。虚空行者（10级，非精英）血量低于30%时很危险：让小鬼攻击它，用{spell:14868}、腐蚀术和{spell:348}，它靠近时用恐惧。如果它打败你，再用一次项圈。项圈要留着：{npc:6122}会收回。",
	["Summoned Voidwalker"] = "被召唤的虚空行者",
	["Surena Caledon"] = "苏雷娜·卡莱顿",
	["Voidwalker (Alliance)"] = "虚空行者（联盟）",
	["Warlock"] = "术士",
	["Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in {npc:6122}'s crypt."] = "10级时的坦克恶魔：虚空行者，需要先拿到黑暗女巫的项圈，再在{npc:6122}的墓穴里打一场。",
	["{item:6928}, on the circle in the crypt"] = "{item:6928}，在墓穴的法阵上",
	["{npc:6121}, Lion's Pride Inn cellar"] = "{npc:6121}，狮王之傲旅店地窖",
	["{npc:881} (level 9) is inside the farmhouse at the {area:62}, south-east Elwynn near the Redridge road. {npc:473} (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on {npc:881} first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop."] = "{npc:881}（9级）在{area:62}的农舍里，位于艾尔文森林东南、靠近赤脊山道路。{npc:473}（10级）和一名战士与她站在一起，会加入战斗；摩根会凿击并攻击你的小鬼，所以让他一直处于恐惧状态。先给{npc:881}上持续伤害，恐惧其他人，在解决他们之前先拾取她的项圈：即便之后你死了，项圈也归你。她从远处扔火球，死后三分钟刷新。杀她之前要先接到任务，否则项圈不会掉落。",
	["{quest:1685} (Humans)"] = "{quest:1685}（人类）",
	["{quest:1715} (Gnomes)"] = "{quest:1715}（侏儒）",
	["{quest:1715} is the tavern in the {object:2101}; {npc:6122} is in its cellar, down the stairs inside."] = "{quest:1715}是{object:2101}里的旅店；{npc:6122}在其地窖，从里面楼梯下去。",
}

G["forever/collectibles/mounts/alliance/paladin-warhorse"] = {
	["At 40 {npc:6179}, upstairs in the {object:32386}, sends you to {npc:6171} in {zone:1453} ({npc:5149} downstairs gives the same errand; take one). Take the {area:2257} to {zone:1453}."] = "40级时，{object:32386}楼上的{npc:6179}会让你去找{zone:1453}的{npc:6171}（楼下的{npc:5149}给同样的差事；接一个即可）。乘{area:2257}到{zone:1453}。",
	["Paladin"] = "圣骑士",
	["{npc:6171} stands in the Cathedral of Light. At 40 he offers {quest:1661}: accept it and hand it straight back to learn {spell:13819}. Paladins do not buy a horse."] = "{npc:6171}站在光明大教堂。40级时他会提供{quest:1661}：接受后直接交还，就能学会{spell:13819}。圣骑士不用买马。",
}

