G["forever/alliance/gnome/01-dun-morogh"] = {
	["Back east through {area:131}: the class quests here wait for level 10."] = "向东返回，穿过{area:131}：这里的职业任务要等到10级。",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {area:40} is next, west of {area:87}."] = "回到{npc:6122}。在{object:2164}地窖里的召唤法阵上使用{item:6928}，击败它召唤出的虚空行者。接下来去{area:40}，在{area:87}西边。",
	["Bartleby"] = "巴特莱比",
	["Below ground"] = "地下",
	["Burly Rockjaw Trogg"] = "强壮的石颚穴居人",
	["Class trainer"] = "职业训练师",
	["Dark Iron Spy"] = "黑铁间谍",
	["Druid trainer"] = "德鲁伊训练师",
	["Elder Crag Boar"] = "老峭壁野猪",
	["Flintfire's shipments lie on the cave floor, and {object:460004} is missing somewhere inside.
Careful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "燧火的货物散落在洞穴地面，{object:460004}则在洞穴某处遗失。
小心：洞穴里的雪怪站得很近，战斗很容易同时引到好几只；在洞外用远程攻击一只一只引出来就能避免。",
	["Follow the road all the way east to the {area:806} at the {area:38} tunnel."] = "沿路一直向东，到{area:38}隧道处的{area:806}。",
	["Follow the road north-east from {area:131} to the depot: the whole east of {area:1} is one sweep from here."] = "从{area:131}沿路向东北前往补给站：{area:1}整个东边都可以从这里一次清完。",
	["Follow the road through the tunnel and north-east to {area:131}. Start outside: {npc:1252} and Eric's campfire are in front of the {area:2102}.
{npc:1872} works the forge west of the distillery.
Then go in: {npc:6806}, the innkeeper, {npc:1226} and {npc:1267}. {npc:1699}'s {skill:185} lesson waits for the return with the ribs, when the copper is there for it."] = "沿路穿过隧道，向东北到{area:131}。从外面开始：{npc:1252}和埃里克的营火在{area:2102}前面。
{npc:1872}在酿酒厂西边的铁匠铺干活。
然后进去：旅店老板{npc:6806}、{npc:1226}和{npc:1267}。{npc:1699}的{skill:185}课程要等你带着肋排回来才教，那时铜币也够了。",
	["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, Tiza and Muiredon on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "沿路走到{zone:1455}，乘坐{object:32362}：{npc:5149}、{npc:6179}和{npc:6178}在{object:32386}里，提扎和缪瑞顿在它的上层：上楼的楼梯就在{npc:5149}东北。乞丐{npc:6175}在城中游荡。他要十块{item:2589}：{area:1}的穴居人和巨魔会掉落，拍卖行也有卖。",
	["Frostmane Headhunter"] = "霜鬃猎头者",
	["Frostmane Troll Whelp"] = "霜鬃巨魔幼崽",
	["Go through the tunnel into {area:38}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "穿过隧道进入{area:38}。刚过隧道，一条用石头标记的小路沿着通往{npc:257808}营地的北路右侧爬上山。",
	["Head back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "离开{zone:1455}往回走，沿路向东到{area:212}。{npc:6177}死在岸边：对他使用{item:6866}。在湖边潜行的黑铁间谍身上带着那份名册。",
	["Ice Claw Bear"] = "冰爪熊",
	["If you skipped {quest:314}, grind here to level 11.41 to stay on the route's plan."] = "如果你跳过了{quest:314}，就在这里刷到11.41级，以符合路线规划。",
	["Inn and flight master"] = "旅店与飞行管理员",
	["Instead of walking back up to {area:1537}, go east through the South Gate tunnel into {area:38} and follow the road north to {area:144}. {npc:1681} stands on the east side of town, past the {area:2101}; his errand pays for a flight back to {area:1537}."] = "不必走回{area:1537}，改为向东穿过南门隧道进入{area:38}，沿路向北到{area:144}。{npc:1681}在小镇东侧、{area:2101}再往前；他的差事报酬足够坐飞机回{area:1537}。",
	["Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. Back in the distillery: {npc:1699} teaches {skill:185}, then the ribs go to {npc:1267}."] = "路上杀峭壁野猪：它们的肋排在接到{npc:1267}的任务前就会掉落，并且算作任务进度。回到酿酒厂：{npc:1699}传授{skill:185}，然后把肋排交给{npc:1267}。",
	["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {area:40}: fill {item:7207} at its base."] = "从正门离开{zone:1453}。{quest:1861}瀑布在城门外西南方，就在向西去{area:40}的路上：在瀑布底部装满{item:7207}。",
	["Level 11.41"] = "11.41级",
	["Minor Ice Elemental"] = "小型冰元素",
	["On the road back west to {zone:1455}."] = "在回西边{zone:1455}的路上。",
	["On the way"] = "顺路",
	["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Rockjaw Bonesnappers prowl the quarry and the lake; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "{area:212}旁、采石场以北的石颚伏击者，以及更东边的石颚碎背者掉落{quest:95214}。石颚碎骨者在采石场和湖边徘徊；黑铁间谍在湖岸潜行。其中一个间谍掉落{item:274268}。",
	["Rockjaw Bonesnapper"] = "石颚碎骨者",
	["Rockjaw Skullthumper"] = "石颚碎颅者",
	["Rockjaw Trogg"] = "石颚穴居人",
	["Small Crag Boar"] = "小型峭壁野猪",
	["Snow Leopard"] = "雪豹",
	["Snow Leopard Prowler"] = "雪豹潜行者",
	["The quarry lies just east of Farsen's ridge."] = "采石场就在法森山脊以东。",
	["The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for {quest:99160}.
Finish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short."] = "三支步枪在营地旁冰湖周围的雪地里。小型冰元素在湖边和路上飘荡：为{quest:99160}一路杀过去。
如果数量还不够，把营地西边小湖周围的小型冰元素也清掉。",
	["The {item:2676} grows in baskets up on {area:802}, the snowy slope north of the road between {area:131} and Brewnall: climb from the road west of {area:131}. The Frostmane Seers camped on the ridge drop it too."] = "{item:2676}长在{area:802}上的篮子里，那是{area:131}与布伦诺尔之间道路以北的雪坡：从{area:131}西边的路上山。山脊上扎营的霜鬃先知也会掉落。",
	["The {item:6775}"] = "{item:6775}",
	["The {object:176785} sits next to {npc:271546}, south of the {area:136}."] = "{object:176785}在{npc:271546}旁边，{area:136}以南。",
	["The {object:270} in the distillery; below ground"] = "{object:270}在酿酒厂里；地下",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1388} is a level 12 elite: most classes solo it at level 14, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人一起做。{npc:1388}是12级精英：大多数职业在14级可以单挑，但你可能需要帮助。如果你独自一人就跳过：路线会让你把经验刷回来。",
	["Tram to {zone:1453}"] = "乘地铁前往{zone:1453}",
	["Upstairs"] = "楼上",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "趁在这里：向{npc:11867}学习法杖（{object:2096}，10银）；猎人的近战武器主要看属性，双手武器加成最多。",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "趁在这里：向{npc:11867}学习法杖（{object:2096}，10银）；升级过程中法杖的法术属性比单手武器多。",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "趁在这里：向{npc:11867}学习剑（{object:2096}，10银）；主手拿剑能让盗贼稳定升级。",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "趁在这里：向{npc:11865}学习{spell:197}（{object:32359}，10银）；双手武器让圣骑士升级最快。",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11865}学习{spell:197}（{object:32359}，10银）；双手武器让战士升级最快。",
	["While you're here: learn {spell:199} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11865}学习{spell:199}（{object:32359}，10银）；双手武器让战士升级最快。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让圣骑士升级最快。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让战士升级最快。",
	["grind on {npc:260157}"] = "刷{npc:260157}",
	["{area:132}: kill these as you meet them"] = "{area:132}：遇到就杀",
	["{area:133}: kill these as you meet them"] = "{area:133}：遇到就杀",
	["{area:138}: kill these as you meet them"] = "{area:138}：遇到就杀",
	["{area:1}: kill these as you meet them"] = "{area:1}：遇到就杀",
	["{item:2004}; below ground"] = "{item:2004}；地下",
	["{item:2667}: the meat locker; below ground"] = "{item:2667}：肉类冷藏柜；地下",
	["{item:2686}, from {npc:1247} in the distillery; upstairs"] = "{item:2686}，来自酿酒厂的{npc:1247}；楼上",
	["{item:2894}, from {npc:1247}; upstairs"] = "{item:2894}，来自{npc:1247}；楼上",
	["{npc:10090} is in the {object:32390}, {npc:258785} in the {object:32386}, {npc:6120} in the {object:32383}."] = "{npc:10090}在{object:32390}，{npc:258785}在{object:32386}，{npc:6120}在{object:32383}。",
	["{npc:1117} along the way to {area:134}"] = "顺路去{area:134}的路上{npc:1117}",
	["{npc:1117} on the way"] = "顺路上的{npc:1117}",
	["{npc:1123}, below ground"] = "{npc:1123}，地下",
	["{npc:1226}, upstairs"] = "{npc:1226}，楼上",
	["{npc:1241}, below ground"] = "{npc:1241}，地下",
	["{npc:1243} camps south-west of it, by the road to Coldridge."] = "{npc:1243}在它西南扎营，靠近去冷岭的路。",
	["{npc:1266} camps in {area:801}, south of the road back east from Brewnall to {area:131}. His meats are in the locker in {npc:1271}'s cave, east of his camp. {npc:1271} is an elite yeti: wait out of sight until he wanders off on his patrol, then take the meats and leave before he comes back. You don't need to fight him."] = "{npc:1266}在{area:801}扎营，位于从布伦诺尔向东返回{area:131}的道路以南。他的肉在{npc:1271}洞穴的冷藏柜里，在营地以东。{npc:1271}是精英雪人：躲起来等他巡逻走开，然后拿走肉，在他回来前离开。不需要和他战斗。",
	["{npc:1269}, below ground"] = "{npc:1269}，地下",
	["{npc:1269}, by the depot; below ground"] = "{npc:1269}，在补给站旁；地下",
	["{npc:1373} guards the {item:2686} barrels in the distillery basement. Buy a {item:2686} from {npc:1247}, click the guarded barrel, then hand the ale to {npc:1373} from his quest window (there is no quest to accept); after that, the unguarded barrel takes the {spell:8553}."] = "{npc:1373}看守酿酒厂地下室的{item:2686}酒桶。先从{npc:1247}买一份{item:2686}，点击有守卫的酒桶，然后在{npc:1373}的任务窗口把酒交给他（没有任务可接）；之后，没有守卫的那个酒桶就能接受{spell:8553}了。",
	["{npc:1373}, beside the barrel; below ground"] = "{npc:1373}，在酒桶旁；地下",
	["{npc:1699}: Camping 101 asks you to learn it; below ground"] = "{npc:1699}：任务“露营入门”要求你学会它；地下",
	["{npc:1960} waits at the {area:808}, north of the South Gate; the dwarven corpse lies up the pass to the west of him."] = "{npc:1960}在南门以北的{area:808}等候；矮人尸体就在他西边的山道上方。",
	["{npc:2756}, inside"] = "{npc:2756}，室内",
	["{npc:276003} along the way to {npc:1253}"] = "顺路去{npc:1253}的路上{npc:276003}",
	["{npc:276003} on the way"] = "顺路上的{npc:276003}",
	["{npc:5505} in {zone:1453}; {area:1} has no druid trainer"] = "{npc:5505}在{zone:1453}；{area:1}没有德鲁伊训练师",
	["{npc:6806}, inside"] = "{npc:6806}，室内",
	["{npc:706} along the way to {npc:786}"] = "顺路去{npc:786}的路上{npc:706}",
	["{npc:706} on the way"] = "顺路上的{npc:706}",
	["{npc:836}, inside {area:77}; below ground"] = "{npc:836}，在{area:77}内；地下",
	["{npc:8416}, at the door on the way out; inside"] = "{npc:8416}，在出门处的门口；室内",
	["{npc:8416}, by the door of {area:77}; inside"] = "{npc:8416}，在{area:77}门口；室内",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
}

G["forever/alliance/nightelf/02-darkshore"] = {
	["Back north-east into the mountains to the crystal."] = "向东北回到山中，前往水晶处。",
	["Bears and the Blackwood camp"] = "熊与黑木营地",
	["Blackwood Pathfinder"] = "黑木探路者",
	["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "黑木探路者和黑木语风者占据着{area:442}东南的营地。",
	["Blackwood Windtalker"] = "黑木语风者",
	["Blackwood furbolgs"] = "黑木熊怪",
	["Boat to {area:17203}"] = "乘船前往{area:17203}",
	["Class trainer"] = "职业训练师",
	["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "爬上{area:447}以东的东部山脉；{object:175524}在岩架上。",
	["Druid trainer"] = "德鲁伊训练师",
	["Fill the tube at the moonwell in the village"] = "在村里的月井处装满管子",
	["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "沿海岸向南经过{area:447}：一件{quest:4728}在树林西边的海岸上，另一件在更南边、{area:450}附近。还有三件遗骸在更西南的灰雾神谕者和潮汐猎人（18-20级）中间：指南把它们留到最后一轮，那时你更接近它们的等级。",
	["Grell Earrings"] = "格里尔耳环",
	["Highborne Relics"] = "上层精灵遗物",
	["Into {area:12}"] = "进入{area:12}",
	["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "在{area:442}东边的丘陵里杀狂暴蓟熊，然后走到它们东南的熊怪营地：现在还没有要杀的东西。",
	["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {object:17183} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "沿丘陵向北。{npc:3650}在{quest:954}的废墟里等候；野生格里尔和邪恶小精灵遍布其中，东边是德塞利尔萨特。{object:17183}在废墟以西的路旁；去他那边的海岸上有一件{quest:4723}。",
	["Plagued bears"] = "染疫的熊",
	["Rabid Thistle Bears roam the hills just east of {area:442}. Use {item:7586} on one and lead it back to him."] = "狂暴蓟熊在{area:442}东边的丘陵游荡。对其中一只使用{item:7586}，把它引回他那里。",
	["Read the {object:17188}"] = "阅读{object:17188}",
	["Read the {object:17189}"] = "阅读{object:17189}",
	["Shaman trainer"] = "萨满祭司训练师",
	["The WANTED poster outside the inn"] = "旅店外的通缉令",
	["The beach"] = "海滩",
	["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "船停靠在村子西边。飞行管理员站在旅店南边的山丘上；任务发布者分散在主街上。",
	["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street. {npc:3666} stands upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "船停靠在村子西边。飞行管理员站在旅店南边的山丘上；任务发布者分散在主街上。{npc:3666}站在旅店楼上：从里面上楼梯，箭头分不清楼层。",
	["The flame burns in the south of {area:447}."] = "火焰在{area:447}的南部燃烧。",
	["The red crystal"] = "红色水晶",
	["The skeletal turtle"] = "骷髅海龟",
	["The southern beaches"] = "南部的海滩",
	["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "潮汐爬行者在村子下方的海岸爬行；{quest:983}站在码头正南的海滩上。黑海岸长尾鲨在浅水中游动。{object:175207}在村子正南的海岸上。",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "趁在这里：向{npc:11867}学习剑（{object:2096}，10银）；主手拿剑能让盗贼稳定升级。",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "趁在这里：向{npc:11867}学习{spell:202}（{object:2096}，10银）；双手武器让战士升级最快。",
	["the Rabid Thistle Bears nearest {npc:3701}"] = "距{npc:3701}最近的狂暴蓟熊",
	["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289}，在码头西边的海滩；水下",
	["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}：德塞利尔萨特",
	["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446}在{zone:1426}；{area:87}没有萨满祭司训练师",
	["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639}站在废墟北缘。被诅咒者、扭曲者和{npc:2178}在废墟里出没；{npc:3667}的鬼魂在中间游荡，{npc:270196}那只猫头鹰在废墟东边盘旋。两块石板在废墟里；废墟西边的海岸上有一件{quest:4722}。",
	["{npc:3649}, north end of the village"] = "{npc:3649}，村子北端",
	["{npc:3666}, upstairs in the inn"] = "{npc:3666}，旅店楼上",
	["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "{npc:5504}在{zone:1453}；{area:87}没有德鲁伊训练师",
	["{zone:1453} flight master"] = "{zone:1453}飞行管理员",
}

G["forever/class/mage/staff-or-orb-alliance"] = {
	["A staff or an off-hand orb at 10 from your home town's mage trainer; Skyborne add a wand."] = "10级时从主城的法师训练师那里拿到法杖或副手宝珠；天裔还会多一根魔杖。",
	["At 10 {npc:1228}, the {area:131} mage trainer in the {area:2102}, sends you to {npc:5144} in {zone:1455}. Taking it shuts out {npc:5497}'s {quest:1861}; you get one staff-or-orb quest. (A Gnome who took {npc:328}'s quest in {area:87} instead follows the {quest:1861} steps; a Human who took this one, the Gizmonitor steps.)"] = "10级时，{area:2102}中{area:131}的法师训练师{npc:1228}派你去找{zone:1455}的{npc:5144}。接受了它，{npc:5497}的{quest:1861}就不会出现；你只能做一条法杖或宝珠任务。（若侏儒在{area:87}接了{npc:328}的任务，则改走{quest:1861}的步骤；若人类接了这条，则走基兹莫尼特的步骤。）",
	["At 10 {npc:252373}, the {area:16638} mage trainer, sends you to {npc:256507}, the staff merchant a few steps away in the same town."] = "10级时，{area:16638}的法师训练师{npc:252373}会让你去找{npc:256507}，那是同镇几步之外的杖类商人。",
	["At 10 {npc:328}, the {area:87} mage trainer, upstairs in the Lion's Pride Inn, sends you to {npc:5497} in {zone:1453}. Taking it shuts out {npc:5144}'s quest in {zone:1455}; you get one staff-or-orb quest."] = "10级时，狮王之傲旅店楼上的{area:87}法师训练师{npc:328}会让你去找{zone:1453}的{npc:5497}。接受了它，{zone:1455}的{npc:5144}的任务就不会出现；你只能做一条法杖或宝珠任务。",
	["Back to {npc:256507}"] = "回到{npc:256507}",
	["Back to {npc:5144}"] = "回到{npc:5144}",
	["Back to {npc:5497}"] = "回到{npc:5497}",
	["Back up the Wizard's Sanctum and through the portal. The orb is an off-hand for a one-hand weapon; the staff is a two-hander."] = "回到巫师圣殿上层，穿过传送门。宝珠是单手武器的副手；法杖是双手武器。",
	["Follow the road north into {zone:1453} and west to the {object:2101}. {npc:5497} stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you {item:7207}. Skyborne mages take {quest:1861} from her when they first reach {zone:1453}, at about 15."] = "沿路向北进入{zone:1453}，再向西到{object:2101}。{npc:5497}站在巫师圣殿顶部，那座高大的紫色塔：沿螺旋坡道向上，走进顶部的传送门，就会到她身旁。她交给你{item:7207}。天裔法师第一次到{zone:1453}时（约15级）会从她那里接{quest:1861}。",
	["Head west along the road to {area:133}. Just north of its entrance stand two huts; the toolbox is in the taller, eastern one, the hut with the lift: a small grey box on the ground floor, half under the table beside the lift. Leper Gnomes (level 8) guard the huts: pull them singly. There is only one toolbox and it takes 15 minutes to come back after someone opens it, so wait nearby if it is gone."] = "沿路向西前往{area:133}。入口正北有两座小屋；工具箱在较高、靠东的那座，也就是带升降机的小屋：一楼的一只灰色小盒子，一半在升降机旁的桌子下面。麻风侏儒（8级）看守着小屋：一只一只拉。工具箱只有一个，被人打开后要15分钟才会重新出现，所以如果它不见了就在附近等。",
	["Leave {zone:1453} by the main gate and head south-west to the waterfall that feeds {quest:1861}. Wade in under the falling water to the rock behind it and use {item:7207} there (a 5 second cast); it fails anywhere else. Level 10 Defias casters stand on the rocks either side of the falls and shoot from range: pull them one at a time or fill the flask from the water."] = "从正门离开{zone:1453}，向西南前往{quest:1861}所对应的瀑布。蹚进落水下方，走到瀑布后的岩石，在那里使用{item:7207}（5秒施法）；在其他任何地方都会失败。10级迪菲亚施法者站在瀑布两侧的岩石上远程射击：一只一只拉，或者直接从水里灌满瓶子。",
	["Ley or {item:9514} or Orb (Alliance)"] = "Ley法杖或{item:9514}或宝珠（联盟）",
	["Mage"] = "法师",
	["The Windstone Formations"] = "风石阵",
	["The bough lies on the ground among the Windstone Formations, the wind shrine on the rise west of Fillion's camp, south of {area:16636}. It does not sparkle, so look at the ground by the stones; there are two spots for it."] = "树枝躺在风石阵之间的地面上，那是菲里昂营地以西高地上的风之神龛，{area:16636}以南。它不会闪光，所以在石头旁的地面上找；有两个可能的位置。",
	["The {quest:1861} waterfall"] = "{quest:1861}瀑布",
	["{item:7207}, under the falls"] = "{item:7207}，瀑布下",
	["{npc:256507}'s quest is open to Human and Gnome mages too, if you ever visit {area:16638} on {zone:2521}, the Skyborne home: {npc:252373}, the town's mage trainer, sends you to {npc:256507} next door, who wants a {item:262668} from the ground by the Windstone Formations south of {area:16636}, for the {item:263430}. It does not shut out the staff or the orb."] = "{npc:256507}的任务也向人类和侏儒法师开放，只要你有一天到访天裔的家园{zone:2521}上的{area:16638}：镇上的法师训练师{npc:252373}会让你去找隔壁的{npc:256507}，他要一个来自{area:16636}以南风石阵旁地面的{item:262668}，用来换{item:263430}。它不会关闭法杖或宝珠任务。",
	["{npc:256507}'s wand (optional)"] = "{npc:256507}的魔杖（可选）",
	["{npc:5144} teaches mages in the {object:32362}, at the back of {zone:1455} past the {object:32386}."] = "{npc:5144}在{object:32362}里教法师，那里是{zone:1455}的后部，穿过{object:32386}就到。",
	["{npc:5144}: {item:7507} or {item:9514}"] = "{npc:5144}：{item:7507}或{item:9514}",
	["{npc:5497}: {item:7508} or {item:9513}"] = "{npc:5497}：{item:7508}或{item:9513}",
	["{quest:1861} (the next steps) waits for you with {npc:5497} in {zone:1453}, at about 15."] = "{quest:1861}（后续步骤）会在{zone:1453}的{npc:5497}那里等你，约15级。",
}

G["forever/class/paladin/holy-mightstone"] = {
	["A one-use stone that makes you much stronger against undead for 10 minutes; the old item choice may be gone in Forever."] = "一次性使用的石头，10分钟内让你对亡灵强得多；在Forever里，旧的物品选择可能已经取消。",
	["At 50 {npc:5149}, the paladin trainer in the {object:32362}, sends you to {area:3197} in the {zone:1422}. {npc:928} in {zone:1453} gives the same quest."] = "50级时，{object:32362}里的圣骑士训练师{npc:5149}会让你去{zone:1422}的{area:3197}。{zone:1453}的{npc:928}给同样的任务。",
	["At 50 {npc:928}, the paladin trainer in the Cathedral of Light, sends you to {area:3197} in the {zone:1422}. {npc:5149} in {zone:1455} gives the same quest."] = "50级时，光明大教堂的圣骑士训练师{npc:928}会让你去{zone:1422}的{area:3197}。{zone:1455}的{npc:5149}给同样的任务。",
	["Back to Ashlam in {area:3197}: he forges the {item:20620}. Look at the reward window before you hand in: Classic also offered the {item:20505}, the {item:20504} or the {item:20512}, and Forever's notes say that choice may be gone. Use the stone before a fight against undead ({area:2279}, {area:2057}): it lasts ten minutes and is gone after one use."] = "回到{area:3197}的阿什兰处：他锻造{item:20620}。交任务前先看奖励窗口：经典版还会提供{item:20505}、{item:20504}或{item:20512}，而Forever的说明称该选择可能已经取消。在与亡灵战斗前使用石头（{area:2279}、{area:2057}）：它持续十分钟，用一次就消失。",
	["Back to {area:3197}. Ashlam needs the voodoo of the {area:1417}'s trolls for the stone."] = "回到{area:3197}。阿什兰需要{area:1417}巨魔的巫毒来制作石头。",
	["Kill the Scourge of the {zone:1422} with the Commission on: skeletons, ghouls and cultists (level 50-58) drop a {item:12840} about two kills in five. {area:197}, just east of {area:3197} around {area:196}, is the closest farm. Avoid the Flesh Golems that patrol the fields; Skeletal Guardians cast {spell:120} and {spell:1449} up close, Dark Summoners run for help at low health."] = "戴着委任徽章在{zone:1422}杀天灾：骷髅、食尸鬼和教徒（50-58级）约五次击杀掉两个{item:12840}。{area:197}，就在{area:3197}以东、{area:196}周围，是最近的刷怪点。避开在田野巡逻的血肉傀儡；骷髅守卫会近身施放{spell:120}和{spell:1449}，黑暗召唤者低血量时会逃跑求援。",
	["Paladin"] = "圣骑士",
	["The Scourge drop no Scourgestones unless you wear an {item:12846}. {npc:10840} gives you one through her quest, {item:12846}, which you hand in straight away (if you already have one from {area:2268}, wear that). Equip it in a trinket slot: it shows as a buff that never runs out. Keep it on until you have 20 stones."] = "除非戴着{item:12846}，否则天灾不会掉落天灾石。{npc:10840}会通过她的任务给你一个{item:12846}，接到后立刻交还（如果你已经从{area:2268}拿到一个，就戴那个）。把它装备在饰品栏：它会显示为一个永不消失的增益。一直戴着，直到你攒够20块石头。",
	["The {item:12846}"] = "{item:12846}",
	["{area:1477}, the {area:1417}, lies in the {area:74} in eastern {zone:1435}: go up the ruin's stairs, dive into the flooded hall and follow the stairs down to the portal. It is a dungeon for a group of five at about 50-55. Six elite troll minibosses (level 51-52) stand on the balconies around the temple's great round room, each behind a pack of elites on its side path. Each drops its feather every time: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green; you need all six. Hukku calls guardians and throws Shadow Bolt Volleys, Mijan heals: kill them first."] = "{area:1477}，即{area:1417}，位于{zone:1435}东部{area:74}里：走上废墟的台阶，潜入被水淹没的大厅，沿楼梯向下走到传送门。这是一个约50-55级五人小队的地下城。六个精英巨魔小头目（51-52级）站在神庙大圆厅周围的阳台上，各自守在其侧路的一群精英之后。它们每次都会掉落自己的羽毛：加舍尔和琥珀色的{npc:5716}、胡库和蓝色的米詹、佐洛和绿色的洛罗；六根都需要。胡库会召唤守卫并投掷暗影箭雨，米詹会治疗：先杀它们。",
	["{area:3197} is the Alliance camp at the south end of the {zone:1422}, north of the Alterac foothills. {npc:10838} commands it; {npc:10840} stands in the same camp."] = "{area:3197}是{zone:1422}南端的联盟营地，在奥特兰克丘陵以北。{npc:10838}负责指挥；{npc:10840}也在同一营地。",
	["{item:12840} x20"] = "{item:12840} x20",
	["{item:12846}: equip it"] = "{item:12846}：装备它",
	["{item:20606} x2: Gasher, {npc:5716}"] = "{item:20606} x2：加舍尔、{npc:5716}",
	["{item:20607} x2: Hukku, Mijan"] = "{item:20607} x2：胡库、米詹",
	["{item:20608} x2: Zolo, Loro"] = "{item:20608} x2：佐洛、洛罗",
	["{npc:1854} keeps watch at {area:196} on {area:197}, east of the camp. He turns your 20 stones into one {item:20612}: keep it."] = "{npc:1854}在营地以东{area:197}的{area:196}守望。他会把你的20块天灾石合成一个{item:20612}：留着它。",
}

G["forever/class/paladin/tome-of-divinity"] = {
	["At 12 {npc:5149}, the paladin trainer in {zone:1455}'s {object:32362}, sends you upstairs to {npc:6179}. The errand is optional, a little XP: {npc:1232} in {area:131} and {npc:928} in {zone:1453} give the same one (taking one closes the others), and {npc:6179} starts the chain without it."] = "12级时，{zone:1455}的{object:32362}里的圣骑士训练师{npc:5149}会派你上楼去找{npc:6179}。这个差事是可选的，能给一点经验：{area:131}的{npc:1232}和{zone:1453}的{npc:928}给同样的任务（接其中一个会关闭其他），而且不接它{npc:6179}也会开启这条任务链。",
	["At 12 {npc:927}, the paladin trainer in {area:87}, sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. The errand is optional, a little XP: {npc:5149} in {zone:1455} gives the same one (taking one closes the other), and {npc:6171} starts the chain without it."] = "12级时，{area:87}的圣骑士训练师{npc:927}会让你去{zone:1453}光明大教堂的{npc:6171}。这个差事是可选的，能给一点经验：{zone:1455}的{npc:5149}给同样的任务（接其中一个会关闭另一个），而且不接它{npc:6171}也会开启这条任务链。",
	["Back to the Cathedral of Light: {npc:6173} takes the script, {npc:6171} teaches you {spell:7328}."] = "回到光明大教堂：{npc:6173}收下名册，{npc:6171}教你{spell:7328}。",
	["Back to the Cathedral. {npc:6171} gives you the {item:6866}; {npc:6173} lies wounded by the altar of the same hall. Keep the symbol: you need it on {npc:6172}. If you lose it, {npc:6171} gives you another (The {item:6866})."] = "回到大教堂。{npc:6171}给你{item:6866}；{npc:6173}受伤躺在同一座大厅的祭坛旁。留着这个符号：在{npc:6172}身上要用到。如果丢了，{npc:6171}会再给你一个（{item:6866}）。",
	["Back up to the {object:32386}: {npc:6178} takes the script, {npc:6179} teaches you {spell:7328}."] = "回到{object:32386}上层：{npc:6178}收下名册，{npc:6179}教你{spell:7328}。",
	["Back upstairs in the {object:32386}. {npc:6179} gives you the {item:6866}; her husband {npc:6178} rests on the same floor. Keep the symbol: you need it on {npc:6177}. If you lose it, {npc:6179} gives you another (The {item:6866})."] = "回到{object:32386}楼上。{npc:6179}给你{item:6866}；她的丈夫{npc:6178}在同一层休息。留着这个符号：在{npc:6177}身上要用到。如果丢了，{npc:6179}会再给你一个（{item:6866}）。",
	["Paladin"] = "圣骑士",
	["Right-click the {item:6775}"] = "右键点击{item:6775}",
	["Right-click the {item:6916}"] = "右键点击{item:6916}",
	["The Dark Iron Spies (level 9-11, twelve of them) sneak around the little house below the lake, just south of Narm; you see them from his hill. About one kill in two drops the {item:6847}. They run for help at low health: finish them or step back. They respawn in three minutes."] = "黑铁间谍（9-11级，共十二个）在湖下方的小屋周围潜行，就在纳姆以南；从他所在的山丘能看见它们。约两次击杀掉一个{item:6847}。它们低血量时会逃跑求援：杀掉它们或者后退。三分钟刷新。",
	["The Defias Rogue Wizards around the big stone tablet east of {npc:6172} carry the {item:6846}: about one kill in two drops it, but some players need many kills. They respawn in three minutes."] = "在{npc:6172}以东那座大石板周围，迪菲亚流氓巫师身上带着{item:6846}：约两次击杀掉一个，但有些玩家杀了很多次才出。三分钟刷新。",
	["The summons (Dwarf)"] = "召唤（矮人）",
	["The summons (Human)"] = "召唤（人类）",
	["The {item:6846}"] = "{item:6846}",
	["The {item:6847}"] = "{item:6847}",
	["The {item:6866}"] = "{item:6866}",
	["{item:2589} x10"] = "{item:2589} x10",
	["{item:6846}: Defias Rogue Wizards"] = "{item:6846}：迪菲亚流氓巫师",
	["{item:6847}: Dark Iron Spies"] = "{item:6847}：黑铁间谍",
	["{item:6866} on {npc:6172}'s body"] = "{item:6866}在{npc:6172}的尸体上",
	["{item:6866} on {npc:6177}'s body"] = "{item:6866}在{npc:6177}的尸体上",
	["{npc:6171} stands inside the Cathedral of Light. He hands you the {item:6775}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6171} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "{npc:6171}站在光明大教堂里。他交给你{item:6775}：在背包里右键点击它来开始下一个任务。如果书上说该任务已完成，就销毁它，再找{npc:6171}要一份新的。如果手上有10块{item:2589}，下一步会用到。",
	["{npc:6171}, Cathedral of Light"] = "{npc:6171}，光明大教堂",
	["{npc:6172} lies dead on {area:56}, the island in {area:86} in eastern Elwynn, on top of one of the mounds around the stone circle. Target his body and use the {item:6866} to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes. The Defias Rogue Wizards on the island (level 9-10) cast {spell:116} from far off: they stand apart, so pull one at a time."] = "{npc:6172}死在{area:56}上，那是艾尔文东部{area:86}中的小岛，就在石阵周围一座土丘顶上。选中他的尸体并使用{item:6866}把他复活，然后与他交谈。如果刚有另一个圣骑士复活了他，他的尸体会在约三分钟内重新出现。岛上的迪菲亚流氓巫师（9-10级）会远程施放{spell:116}：它们站得分散，所以一只一只拉。",
	["{npc:6174} stands at a corner in the middle of the {object:2096}, outside a general goods store. She wants 10 {item:2589}: humanoids drop it (Riverpaw gnolls in {zone:1436} about every other kill, Defias and kobolds a little less), or buy it at the Auction House a few steps away in the {object:2096}."] = "{npc:6174}站在{object:2096}中部的一个转角，一家杂货店门外。她要10块{item:2589}：人形怪会掉落（{zone:1436}的河爪豺狼人约每两次击杀掉一个，迪菲亚和狗头人略少一些），或者在几步之外{object:2096}里的拍卖行购买。",
	["{npc:6175} walks the outer ring of the Commons, past the front gate, the bank and the Auction House. He wants 10 {item:2589}: humanoids drop it ({npc:1245} in {area:131} every time, Dark Iron Ambushers about two kills in five), or buy it at the Auction House on his ring."] = "{npc:6175}在平民区的外环走动，经过前门、银行和拍卖行。他要10块{item:2589}：人形怪会掉落（{area:131}的{npc:1245}每次都掉，黑铁伏击者约五次击杀掉两个），或者在他所在外环的拍卖行购买。",
	["{npc:6177} lies dead in {zone:1426}, not {zone:1432}: east past {area:131}, north-east of Ironband's compound, on the smallest of three little hills between {area:212} and the {object:147516} camp. Target his body and use the {item:6866} to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes."] = "{npc:6177}死在{zone:1426}，而不是{zone:1432}：向东经过{area:131}，在铁带营地东北，{area:212}与{object:147516}营地之间三座小丘中最矮的那座顶上。选中他的尸体并使用{item:6866}把他复活，然后与他交谈。如果刚有另一个圣骑士复活了他，他的尸体会在约三分钟内重新出现。",
	["{npc:6179} stands upstairs in the {object:32386}, in the {object:32362}: take the ramp at the back of the hall. She hands you the {item:6916}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6179} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "{npc:6179}站在{object:32362}里{object:32386}的楼上：走大厅后部的坡道。她交给你{item:6916}：在背包里右键点击它来开始下一个任务。如果书上说该任务已完成，就销毁它，再找{npc:6179}要一份新的。如果手上有10块{item:2589}，下一步会用到。",
	["{npc:6179}, upstairs in the {object:32386}"] = "{npc:6179}，{object:32386}楼上",
	["{spell:7328} (Alliance)"] = "{spell:7328}（联盟）",
	["{spell:7328} at 12, the paladin's resurrection: an easy chain through your capital and its home zone."] = "12级的{spell:7328}，圣骑士的复活术：一条轻松的任务链，跑遍你的主城及其所属区域。",
}

G["forever/collectibles/mounts/alliance/horse"] = {
	["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "任何联盟种族都能买这些马，但骑乘还需要{spell:824}，只有人类能随{skill:762}获得。其他种族达到{faction:72}崇拜后可由{npc:4732}教授（暴风城声望攻略给出了路线）。在此之前，别给这个角色买马。",
	["The {npc:5404} is not at {npc:384}: {npc:1460} sells it, at the stables of {area:150} in the {zone:1437} (20g in the Forever client). Skip this unless you want that colour."] = "{npc:5404}不在{npc:384}处：它由{npc:1460}出售，地点在{zone:1437}的{area:150}马厩（Forever客户端里20金）。除非你想要那个颜色，否则跳过。",
	["{item:2411}, 20g, {npc:1460}"] = "{item:2411}，20金，{npc:1460}",
	["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 40 {npc:4732} teaches {skill:762} to Humans for 100g (10% less at Honored with {faction:72}), and it comes with a horse. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4732}和{npc:384}的马厩在{zone:1429}东部的{area:88}。40级时{npc:4732}以100金教人类{skill:762}（{faction:72}尊敬时便宜10%），并附赠一匹马。其他种族在本族的骑术训练师处学习{skill:762}，同时获得自己的第一只坐骑。",
	["{npc:5404} in {area:150}"] = "{npc:5404}在{area:150}",
	["{spell:824} for other races"] = "其他种族的{spell:824}",
}

G["forever/collectibles/mounts/alliance/pack-kodo"] = {
	["The camp is at {area:1002} in western {zone:1433}, where the roads from {zone:1429}, {zone:1431} and {area:69} meet. {npc:256736} sells the {npc:10636} only once you are Exalted with the {faction:2586}, and it costs 6,000 Merchant's Favor. Crates pay only Favor (about 15 a crate return); the reputation comes from Craftsman's Writs and the one-time {item:280179}, so follow the Supply Factions Reputation guide and keep 6,000 Favor aside."] = "营地位于{zone:1433}西部的{area:1002}，来自{zone:1429}、{zone:1431}和{area:69}的道路在此交汇。只有当你在{faction:2586}的声望达到崇拜后，{npc:256736}才出售{npc:10636}，价格为6,000点商人的恩惠。交板条箱只给恩惠（每次交还约15点）；声望来自工匠令状和一次性的{item:280179}，所以请参照补给声望指南进行，并预留出6,000点恩惠。",
	["{faction:2586} camp"] = "{faction:2586}营地",
}

G["forever/collectibles/mounts/alliance/saber"] = {
	["Any Alliance race can buy these sabers, but riding one also takes {spell:828}, which only Night Elves get with {skill:762}. {npc:4753} teaches it to other races once they are Exalted with {faction:69} (the Darnassus Reputation guide shows the way). Until then, don't buy a saber for this character."] = "任何联盟种族都能买这些夜刃豹，但骑乘还需{spell:828}，只有暗夜精灵随{skill:762}获得。其他种族在{faction:69}达到崇拜后，{npc:4753}会教它（达纳苏斯声望指南有路线）。在此之前，别为这个角色买夜刃豹。",
	["new in Forever, 20g; beta players found it here"] = "Forever新增，20金；测试服玩家在这里发现",
	["{npc:4753} and {npc:4730}'s sabers are in the {area:1658}'s riding grounds in {faction:69}. At 40 {npc:4753} teaches {skill:762} to Night Elves for 100g (10% less at Honored with {faction:69}), and it comes with a saber. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4753}和{npc:4730}的夜刃豹在{faction:69}的{area:1658}骑术训练场。40级时{npc:4753}以100金教暗夜精灵{skill:762}（{faction:69}尊敬时便宜10%），并附赠一只夜刃豹。其他种族在本族的骑术训练师处学习{skill:762}，同时获得自己的第一只坐骑。",
	["{spell:828} for other races"] = "其他种族的{spell:828}",
}

G["forever/alliance/30-40/05-arathi-highlands"] = {
	["Argus Shadow Mage"] = "阿古斯暗影法师",
	["Back west through {zone:1430} to {area:42}."] = "向西穿过{zone:1430}回到{area:42}。",
	["Below ground"] = "地下",
	["Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.
Careful: About three stealthed Syndicate mobs are inside {npc:2320}'s house. {npc:2320} does not join when they are pulled, and a ranged attack through the doorway brings him out by himself."] = "注意：辛迪加间谍和刺客可能处于潜行。刺客还会对你下毒。
注意：{npc:2320}的屋里有大约三个潜行的辛迪加怪物。拉它们时{npc:2320}不会加入战斗，隔着门口用远程攻击可以把他单独引出来。",
	["Daggerspine Raider"] = "刺脊袭击者",
	["Daggerspine Sorceress"] = "刺脊女巫",
	["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}.
Careful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "每把钥匙都在高地的一处立石阵：碎片东边、{area:320}附近和西边。{object:2702}立在{area:320}西侧。
注意：每根中央石柱旁都有大约三个39级左右的元素守卫，不先清掉就点石柱会被它们一起攻击：西边是燃烧的流放者，外圈是雷霆流放者，东边是涌潮流放者。",
	["Ebenezer Rustlocke"] = "埃比尼泽·锈锁",
	["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves.
Careful: The ambush is two level 40 water elementals, and they are immune to frost. If the fight happens inside the cave, the professor joins in instead of working and further elementals keep appearing; holding the elementals at the cave entrance, away from him, lets him finish with only the first two to deal with."] = "护送教授到海湾以北的沙滩，并在他工作时守护他；纳迦会一波波来袭。
注意：伏击是两个40级的水元素，且免疫冰霜。如果战斗发生在洞内，教授会参战而不工作，还会不断出现更多水元素；把水元素挡在洞口、远离他，他就能只对付最初那两个并完成工作。",
	["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings, and {npc:2306} walks the manor grounds on the north side of town."] = "沿路向北离开{area:271}进入山区。山地狮在坡上游荡；{area:280}的辛迪加成员戴着印章戒指，{npc:2306}在小镇北侧的庄园里走动。",
	["From {zone:1455} take the tunnel east through {zone:1426} into {area:38} and follow the road to {area:144}."] = "从{zone:1455}经隧道向东穿过{zone:1426}进入{area:38}，再沿路前往{area:144}。",
	["Hay Weevil"] = "干草象鼻虫",
	["Head back north-east past {area:320}; {npc:2712} and {npc:2713} camp in the hills north of {area:314}."] = "向东北返回，经过{area:320}；{npc:2712}和{npc:2713}在{area:314}以北的丘陵扎营。",
	["Hulking Mountain Lion"] = "壮硕山地狮",
	["Inside"] = "室内",
	["Mountain Lion"] = "山地狮",
	["Shadowy Assassin"] = "暗影刺客",
	["Sorrow Spinner"] = "悲伤纺丝蛛",
	["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {area:130}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "向西南前往{area:279}以西湖岸的肯瑞托营地，刚过边界进入{area:130}：{npc:269127}就立在那里。大法师安斯雷姆站在它东南侧、圆顶旁。",
	["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way.
Careful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "跟着{npc:2713}，她潜行进入{area:314}再返回；部落兽人会在途中伏击你。
注意：残血的兽人会逃跑。{npc:2713}会追上去，可能多拉怪，所以要迅速杀死或减速逃跑者。",
	["Summoned Incubus"] = "被召唤的男魅魔",
	["Swamp Jaguar"] = "沼泽美洲豹",
	["Syndicate Highwayman"] = "辛迪加路霸",
	["Syndicate Mercenary"] = "辛迪加雇佣兵",
	["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop both the motes and Krazek's ore.
Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "枯须狗头人在{area:321}以东的峡谷里挖掘（部落区域）；从北边绕过小镇。它们既掉密斯莱尔之尘，也掉克拉兹克的矿石。
注意：所有狗头人残血时都会跑去求援（狗头人30%，勘测员和掘地工15%），可能引来更多同类。",
	["The Syndicate hold the farm north-west of {area:320}. A {npc:217589} crawls about the farm: catch one with {npc:217412}'s Entomology Starter Kit, then tick it off.
Careful: Syndicate Highwaymen are level 30-31 and can cast Sneak while out of combat, so they are often stealthed and hard to spot."] = "辛迪加占据着{area:320}西北的农场。一只{npc:217589}在农场里爬动：用{npc:217412}的昆虫学入门工具包抓住一只，然后勾掉任务。
注意：辛迪加路霸是30-31级，能在脱战时施放潜行，因此常常处于潜行状态，很难发现。",
	["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins.
Careful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health."] = "典籍在{area:280}以西的废弃堡垒里；阿古斯暗影法师占据着废墟。
注意：碎山好战者血量降到一半以下后，会呼叫15码内的附近盟友。",
	["The wrecked caravan lies off the road near Biggs.
Careful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "损毁的车队在比格斯附近的道路旁。
注意：营地到处是38级左右的失落者。它们以2-3只连组行动，其中许多是施法者，且刷新很快。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{npc:2417}是40级精英：大多数职业42级可以单挑，但可能需要帮忙。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["Tram to {zone:1455}"] = "乘地铁去{zone:1455}",
	["Walk back onto the span: Ebenezer lies under its Arathi end."] = "走回桥面：埃比尼泽躺在桥的阿拉希一端下方。",
	["Young Sawtooth Crocolisk"] = "年幼的锯齿鳄",
	["{area:280}: kill these as you meet them"] = "{area:280}：遇到就杀",
	["{area:281}: kill these as you meet them"] = "{area:281}：遇到就杀",
	["{area:318}: kill these as you meet them"] = "{area:318}：遇到就杀",
