	["{item:4435} from {npc:2572}, {npc:2573} and {npc:2574}, by this stop"] = "在本站旁从{npc:2572}、{npc:2573}和{npc:2574}处拿{item:4435}",
	["{item:4492}; underwater"] = "{item:4492}；水下",
