	["{npc:5476} stands by the road junction in the west of the swamp."] = "{npc:5476}站在沼泽西部的路口旁。",
	["{npc:737}, upstairs"] = "{npc:737}，楼上",
	["{npc:773}, upstairs"] = "{npc:773}，楼上",
