	["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260}在旅店附近；南边几步的商人{npc:4897}出售加尔想要的香料。",
	["{quest:1260}, inside"] = "{quest:1260}，室内",
