G["forever/alliance/40-50/04-tanaris"] = {
	["Boat to {area:150}"] = "乘船前往{area:150}",
	["Careful: Thieves cast Disarm. Rogues stay hidden with Sneak. Assassins use Execute when your health is at 20% or lower."] = "注意：窃贼会施放缴械。盗贼用潜行保持隐蔽。刺客在你血量20%或更低时使用斩杀。",
	["Dunemaul Brute"] = "砂槌蛮兵",
	["Dunemaul Enforcer"] = "砂槌打手",
	["Fly to Theramore"] = "飞往塞拉摩",
	["Fly to {area:348}"] = "飞往{area:348}",
	["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.
Careful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "沿海岸向南前往海盗湾。南海海盗挤满沙滩和船只：沿边缘行动，一次拉一只。{npc:7883}在对面；{npc:7881}被偷的货物在营地里。
注意：有两三个海盗和{npc:7883}站在一起，战斗一开始还会有更多镇上的海盗加入。",
	["Gnarled Thistleshrub"] = "多节的蓟灌木",
	["Gor'marok the Ravager"] = "蹂躏者戈玛洛克",
	["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.
Careful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "骑马向西返回{area:976}。废土强盗和窃贼占据着路上的沙丘；其中任何一个都可能带着水袋。
注意：废土盗贼（43-44级）潜行移动，可能悄悄靠近。",
	["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.
Careful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "骑马向西北前往沙丘中的森提帕虫巢。任何森提帕虫都可能掉落昆虫部件。
注意：森提帕群居者不论战斗内外都会施放{npc:4196}，召来打断你的小增援。",
	["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.
Careful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs."] = "骑马向南进入{quest:3362}。露水收集者掉落露腺；只有部分是饱满的，因此只留饱满的那一个。多节的蓟灌木和塑根者共处山谷。蓟灌木是48-50级，高于你：一次拉一只。
注意：该区域其他蓟灌木怪是49-50级，且活动范围广，很容易多拉怪。",
	["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.
Careful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "骑马向南经过{area:1938}前往{area:981}，即哈扎利隧道；斯克林克的装备在深处。
注意：一只虫子守着装备。许多虫子在隧道里巡逻，其中一些是50级，所以战斗常会多拉怪。",
	["Ride south-east off the {area:439} into {area:440}. {area:976} is just inside the border."] = "骑马向东南离开{area:439}进入{area:440}。{area:976}就在边界内侧。",
	["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first.
Careful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "骑马向东南前往{area:985}。{npc:7847}站在废土营地南部的中央：先清掉他周围。
注意：两名潜行的废土盗贼跟着他移动。在他的刷新营地，两名暗法师及其仆从距离很近，能加入与他的战斗。在塔楼外则可以不受他们干扰地打他。",
	["Southsea Dock Worker"] = "南海码头工人",
	["Southsea Freebooter"] = "南海劫掠者",
	["Southsea Pirate"] = "南海海盗",
	["Southsea Swashbuckler"] = "南海剑客",
	["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.
Careful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "更强的废土盗贼、暗法师和刺客在{area:976}东南、强盗南边扎营。把南营地中央的{npc:7847}留到后面。
注意：废土盗贼在脱战时保持潜行，因此藏着的盗贼可能加入你在营地挑起的战斗。",
	["The {area:2240} lies on the {area:439} in south-east {area:400}. {npc:4454} and {npc:4630} are in the camps beside the track.
{npc:4709} stands by the goblin camp.
While {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "{area:2240}位于{area:400}东南的{area:439}上。{npc:4454}和{npc:4630}在赛道旁的营地。
{npc:4709}站在地精营地旁。
趁{npc:4709}缠住里兹尔说话时，他的计划就无人看守地放在赛道对面的侏儒营地里。",
	["Thistleshrub Rootshaper"] = "蓟灌木塑根者",
	["Underwater"] = "水下",
	["Wastewander Assassin"] = "废土刺客",
	["Wastewander Bandit"] = "废土强盗",
	["Wastewander Rogue"] = "废土盗贼",
	["Wastewander Shadow Mage"] = "废土暗法师",
	["Wastewander Thief"] = "废土窃贼",
	["grind on {npc:5474}"] = "刷{npc:5474}",
	["{area:1336}: kill these as you meet them"] = "{area:1336}：遇到就杀",
	["{area:150} flight master"] = "{area:150}飞行管理员",
	["{area:1937}: kill these as you meet them"] = "{area:1937}：遇到就杀",
	["{area:976} flight master"] = "{area:976}飞行管理员",
	["{item:8593}; below ground"] = "{item:8593}；地下",
	["{npc:12046}, below ground"] = "{npc:12046}，地下",
	["{npc:5594}, inside"] = "{npc:5594}，室内",
	["{npc:7583}'s next ingredient grows in the {area:47}, and the route never brings it back: skip it."] = "{npc:7583}下一种材料生长在{area:47}，而路线不会再回到那里：跳过它。",
	["{npc:7881}, in the port's tavern; inside"] = "{npc:7881}，在港口酒馆里；室内",
	["{npc:7881}, inside"] = "{npc:7881}，室内",
	["{npc:7882}, inside"] = "{npc:7882}，室内",
	["{object:20805}, inside"] = "{object:20805}，室内",
	["{quest:2873}; upstairs"] = "{quest:2873}；楼上",
	["{quest:3362}: kill these as you meet them"] = "{quest:3362}：遇到就杀",
}

G["forever/class/paladin/cloak-of-the-divine-storm"] = {
	["A rare cloak at 30 from the old {spell:407778} story; for now only Alliance paladins can finish it."] = "30级可获得的一件稀有披风，出自旧的{spell:407778}任务线；目前只有联盟圣骑士能完成它。",
	["Back to {npc:3663} at {area:413} in western {zone:1440}, across the whole zone."] = "回到{zone:1440}西部{area:413}的{npc:3663}处，要横穿整个区域。",
	["Climb to the top of the {area:444} in northern {zone:1439}. The Dark Strand Fanatics around it are easy (level 16-17), but four Dark Strand Voidcallers (level 28-29) stand in the tower on the way to the orb: each calls a voidwalker and casts {spell:686} from range. At 22-25 bring a friend or two, pull them one at a time and step behind a wall so they have to come to you. Loot the Strange Orb at the top: it gives you the Althalaxx Orb; right-click it to start the quest. Keep the orb in your bags until the {object:409311}: three later quests need it."] = "爬到{zone:1439}北部{area:444}的顶端。周围的暗滩狂热者很好对付（16-17级），但通往法球的塔里有四个暗滩虚空召唤者（28-29级）：每个都会召唤一个虚空行者并从远处施放{spell:686}。22-25级时带一两个朋友，一次拉一个，并躲到墙后，迫使他们走过来。在顶端拾取奇怪的法球：它会变成奥萨拉克斯法球；右键点击以开启任务。把法球留在包里直到{object:409311}：之后有三个任务需要它。",
	["Paladin"] = "圣骑士",
	["The Blackrock Summoners, Champions and Trackers (level 22-25, not elite) camp in the north-west of Redridge and drop the {item:209778}; you need 14. Two elite Blackrock Shadowcasters (22-23) stand at the cave mouth at the camp's east end: pull around them. The Blackrock camps east of {area:69} drop the salt too, but their Shadowcasters, Sentries and Hunters are elite (level 21-24), and so is {npc:334} (26): stay in the north-west."] = "黑石召唤者、勇士和追踪者（22-25级，非精英）在赤脊山西北部扎营，掉落{item:209778}；你需要14个。两个精英黑石暗影法师（22-23级）站在营地东端的洞口：绕开他们拉怪。{area:69}以东的黑石营地也掉这种盐，但那里的暗影法师、哨兵和猎人是精英（21-24级），{npc:334}（26级）也是：留在西北部。",
	["The {object:409311} stands at the east end of {area:435}. Hand in the motes at the spear with the Althalaxx Orb in your bags: the orb shatters, and the {object:409315} beside it starts the last quest."] = "{object:409311}立在{area:435}东端。带着奥萨拉克斯法球在长矛处交付微粒：法球会碎裂，旁边的{object:409315}会开启最后一个任务。",
	["{area:435} is in south-east {zone:1440}, east of {area:431} (a Horde camp: go round it). The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds (level 29-30, not elite) drop the Motes of Mannoroth; you need 12. Below about 27 they are hard alone: come with a second player or later. Felguards knock you down, Lashers cast {spell:686} and {spell:348}, Infernals keep a fire shield up. They respawn in five minutes."] = "{area:435}位于{zone:1440}东南、{area:431}以东（部落营地：绕过去）。玛诺洛克鞭笞者、灼热的地狱火、恶魔卫士和军团猎犬（29-30级，非精英）掉落玛诺洛斯微粒；你需要12个。低于约27级时单人会很难：带另一名玩家或以后再来。恶魔卫士会把你击倒，鞭笞者施放{spell:686}和{spell:348}，地狱火保持火焰护盾。它们五分钟刷新。",
	["{npc:3663} stands at {area:413} in western {zone:1440}, south of the {zone:1439} road. He sends you to {zone:1453} with the orb."] = "{npc:3663}站在{zone:1440}西部的{area:413}，在{zone:1439}道路以南。他让你带着法球前往{zone:1453}。",
	["{npc:5492} stands in the Cathedral of Light; she sends you to a warlock for a second opinion."] = "{npc:5492}站在圣光大教堂；她让你去找一名术士求证。",
	["{npc:5495}, the warlock trainer, is in the {object:2101}'s warlock sanctum, down in the {object:2164}'s cellar. She wants 14 {item:209778} to read the orb."] = "术士训练师{npc:5495}在{object:2101}的术士圣所里，位于{object:2164}的地下室。她需要14个{item:209778}来解读法球。",
}

G["forever/class/paladin/verigans-fist"] = {
	["At 20 {npc:6179}, upstairs in the {object:32386} in the {object:32362}, gives you the {item:6776}. Right-click it: it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the {area:2257} from {zone:1455} to {zone:1453}."] = "20级时，{object:32362}中{object:32386}楼上的{npc:6179}会给你{item:6776}。右键点击它：它会让你去{zone:1453}圣光大教堂的{npc:6171}处。乘{area:2257}从{zone:1455}到{zone:1453}。",
	["Back to the Cathedral of Light: {npc:6171} gives you the {item:9607} shield and teaches you {spell:5502}."] = "回到圣光大教堂：{npc:6171}给你{item:9607}盾牌，并教你{spell:5502}。",
	["Bring the four parts to {npc:6181} outside {zone:1455}. Accept his last quest and wait by him while he forges the mace at his anvil."] = "把四件部件带给{zone:1455}城外的{npc:6181}。接受他最后一个任务，并在他在铁砧上锻造战锤时守在他身旁。",
	["Paladin"] = "圣骑士",
	["Protect {npc:6182}: three waves"] = "保护{npc:6182}：三波",
	["Right-click the {item:6776}"] = "右键点击{item:6776}",
	["The Alliance paladin's rare two-handed mace for the 20s, with a shield and {spell:5502} on the way."] = "联盟圣骑士20级阶段的稀有双手锤，附带一面盾牌，路上还教你{spell:5502}。",
	["The Blackfathom naga in the flooded passages around the {area:2797} entrance, on {zone:1440}'s north-west coast, drop the {item:6995}: Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24), one in two. You do not need to enter the instance. All are elite: grouping up is encouraged; players solo them one at a time, with difficulty. They heal themselves, run for help at low health, satyrs stand near some, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group."] = "{zone:1440}西北海岸{area:2797}入口周围的水淹通道里，黑渊纳迦掉落{item:6995}：潮汐女祭司（20-21级）、神谕者（21-22级）和海巫（23-24级），约每两只掉一个。你不需要进入副本。它们全是精英：建议组队；玩家们通常一次单挑一只，但很困难。它们会自疗，残血时跑去求援，有些旁边站着萨特，海巫会近身施放{spell:122}。有玩家反映在团队中不掉落。",
	["The crate of ore sits outdoors in the middle of the Mo'grosh ogre camp in north-east {zone:1432}, beside a big tree and a broken wagon, between the caves. The camp holds about fifteen Mo'grosh ogres, elite (level 18-19), who knock you down and come back after five minutes: grouping up is encouraged; at 20-22 it needs a group of about three. The crate is back two seconds after each loot, so every paladin in the group gets one."] = "矿石箱露天放在{zone:1432}东北部莫格罗什食人魔营地的中央，在一棵大树和一辆破车旁，位于洞穴之间。营地约有十五个莫格罗什食人魔，精英（18-19级），会把你击倒并在五分钟后回来：建议组队；20-22级时大约需要三人小队。每次拾取后两秒箱子就会刷新，所以队伍里每个圣骑士都能拿到一个。",
	["{area:1581} is a group of five under {area:20}; the instance portal is at the bottom of the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time."] = "{area:1581}是{area:20}下方的一个五人副本；副本传送门在{area:20}矿坑底部。桅杆室里斯尼德身边的哥布林木雕师（精英，18-19级）每次都掉落木材。",
	["{area:236} is a dungeon for a group of five in the low to mid 20s, in southern {zone:1421}, Horde land: a long trip for the Alliance, through the {zone:1437}, Arathi and {area:287}. The hammer lies on a crate across from the horses in the stables, early in the dungeon, at the far end of the courtyard before the ramp up; it is back five minutes after someone takes it."] = "{area:236}是适合20级出头到25级左右的五人地下城，位于{zone:1421}南部，属于部落领地：对联盟来说路途遥远，要穿过{zone:1437}、阿拉希和{area:287}。战锤在副本前段、上坡前的院子尽头，马厩里马匹对面的箱子上；有人拿走后五分钟刷新。",
	["{npc:3649} is in {area:442}. Take his quest before you hunt naga: the Kor Gem never drops without it."] = "{npc:3649}在{area:442}。猎杀纳迦前先接他的任务：没有任务时柯尔宝石绝不会掉落。",
	["{npc:6171} stands in the Cathedral of Light. Humans get the {item:6776} from him. Right-click the book to start its quest and hand it straight back to him."] = "{npc:6171}站在圣光大教堂。人类可以从他那里拿到{item:6776}。右键点击书本来开启它的任务，然后直接交还给他。",
	["{npc:6181} works outside the gates of {zone:1455}, not inside. He gives you {item:6996}: four parts, in any order. Keep the notes."] = "{npc:6181}在{zone:1455}城门外工作，不在城内。他给你{item:6996}：四件部件，顺序不限。保留笔记。",
	["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}, south of {area:20}: take the path that runs south beside the {area:1581}' back exit. When you take her quest, she walks from her orchard to the house and three waves of Defias Raiders (level 17-18) attack: three, then four, then five. Fight close to her so they do not swarm her, and heal her when she drops. You get time to eat and drink between waves, and she heals to full. If you or {npc:6182} die, the quest fails: abandon it and take it again from her (she is back five minutes after dying). Players find it hard alone before about 24."] = "{npc:6182}的农舍在{zone:1436}西南海岸、{area:20}以南：走{area:1581}后出口旁向南的小路。接她的任务后，她会从果园走向农舍，三波迪菲亚袭击者（17-18级）会来袭：先三个，再四个，然后五个。靠近她战斗，免得他们围攻她；她血量下降时给她治疗。两波之间你有时间吃喝，她也会回满血。如果你或{npc:6182}死亡，任务失败：放弃任务再找她接（她死后五分钟回来）。玩家普遍觉得24级前单人很难。",
	["{npc:6241} is downstairs in the house of {area:144} that has a tailoring merchant outside. His quest only opens once you hold Jordan's."] = "{npc:6241}在{area:144}那栋外面有裁缝商人的房子楼下。只有你持有乔丹的部件后，他的任务才会开放。",
	["{npc:6241} turns the ore into {item:6993}, the part Jordan wants."] = "{npc:6241}把矿石变成{item:6993}，也就是乔丹想要的那件部件。",
}

G["forever/class/priest/priest-robes-alliance"] = {
	["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "5级免费拿一件优秀品质长袍：治疗并加持一名在你第一个镇子附近受伤的卫兵。",
	["At 5, {npc:3595}, the priest trainer on the second level of {area:256}, the great tree in {area:188}, sends you to {npc:3600} in {area:186}. Train {spell:613} (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "5级时，{area:188}中巨树{area:256}二楼的牧师训练师{npc:3595}会让你去找{area:186}的{npc:3600}。既然来了，就向她学习{spell:613}（2级）：该技能4级开放，花费1银，下一个任务正好需要这个等级。",
	["At 5, {npc:375}, the priest trainer inside {area:24}, sends you to {npc:377} in {area:87}. Train {spell:613} (Rank 2) from Anetta while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "5级时，{area:24}内的牧师训练师{npc:375}会让你去找{area:87}的{npc:377}。既然来了，就向安妮塔学习{spell:613}（2级）：该技能4级开放，花费1银，下一个任务正好需要这个等级。",
	["At 5, {npc:837}, the priest trainer inside {area:77} in {area:132}, sends you to {npc:1226} in {area:131}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "5级时，{area:132}中{area:77}内的牧师训练师{npc:837}会让你去找{area:131}的{npc:1226}。既然来了，就向他学习{spell:613}（2级）：该技能4级开放，花费1银，下一个任务正好需要这个等级。",
	["Back at the north edge of {area:186}: {npc:3600} gives you the {item:16604}."] = "回到{area:186}北缘：{npc:3600}给你{item:16604}。",
	["Back inside the {area:2102}: {npc:1226} gives you {item:16605}."] = "回到{area:2102}内：{npc:1226}给你{item:16605}。",
	["Back upstairs in the Lion's Pride Inn: Josetta gives you {item:16605}."] = "回到狮王之傲旅店楼上：乔塞塔给你{item:16605}。",
	["Follow the road south out of {area:9} to {area:87}. {npc:377} is upstairs in the Lion's Pride Inn."] = "沿路向南离开{area:9}前往{area:87}。{npc:377}在狮王之傲旅店楼上。",
	["Guard Roberts"] = "卫兵罗伯茨",
	["Heal and fortify {npc:12423}"] = "治疗并加持{npc:12423}",
	["Heal and fortify {npc:12427}"] = "治疗并加持{npc:12427}",
	["Heal and fortify {npc:12429}"] = "治疗并加持{npc:12429}",
	["Leave {area:188} by the ramp and follow the road south-west to {area:186}. {npc:3600} is in the building at the north edge of the village."] = "从斜坡离开{area:188}，沿路向西南前往{area:186}。{npc:3600}在村北缘的建筑里。",
	["Mountaineer Dolf"] = "巡山者多尔夫",
	["Priest"] = "牧师",
	["Priest Robes at 5 (Alliance)"] = "5级牧师长袍（联盟）",
	["Sentinel Shaya"] = "哨兵沙娅",
	["Take the tunnel north-east out of {area:132} and follow the road east to {area:131}. {npc:1226} is inside the {area:2102}."] = "从{area:132}走隧道向东北出去，再沿路向东前往{area:131}。{npc:1226}在{area:2102}内。",
	["{npc:12423} kneels by a tree on the lake shore east of {area:87}, off the road: walk along the shore, the minimap misses him from the road. Cast {spell:613} (Rank 2) on him first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook (or cast both from the spellbook if an action bar addon gets in the way). He walks off once both land and is back in about 3 minutes."] = "{npc:12423}跪在{area:87}以东湖岸边的一棵树旁，不在路上：沿湖岸走，从路上看小地图会漏掉他。先对他施放{spell:613}（2级），再放{spell:1243}。{spell:613}的1级不算数；从法术书中把2级拖到动作条上（如果动作条插件碍事，就直接从法术书施放两个法术）。两个法术都命中后他就会走开，大约3分钟后回来。",
	["{npc:12427} kneels on a ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer: if the road starts going downhill, you have passed him. Cast {spell:613} (Rank 2) on him first, then {spell:1243}; he speaks after each spell. Rank 1 of {spell:613} does not count."] = "{npc:12427}跪在{area:131}正南两道矮墙之间的山脊上，在猎人宠物训练师的路对面：如果路开始下坡，说明你已经走过他了。先对他施放{spell:613}（2级），再放{spell:1243}；他会在每个法术之后说话。{spell:613}的1级不算数。",
	["{npc:12429} kneels on the rocks at the edge of {area:259}, about 100 yards south of {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her first, then {spell:1243}; she runs off toward the lake once both land and is back in about 5 minutes. Rank 1 of {spell:613} does not count."] = "{npc:12429}跪在{area:259}边缘的岩石上，位于{area:186}以南约100码，头顶没有任务标记。先对她施放{spell:613}（2级），再放{spell:1243}；两个法术都命中后她会朝湖跑去，大约5分钟后回来。{spell:613}的1级不算数。",
	["{spell:613} (Rank 2), if Anetta did not teach it yet"] = "{spell:613}（2级），如果安妮塔还没教你",
	["{spell:613} (Rank 2), if {npc:3595} did not teach it yet"] = "{spell:613}（2级），如果{npc:3595}还没教你",
	["{spell:613} (Rank 2), if {npc:837} did not teach it yet"] = "{spell:613}（2级），如果{npc:837}还没教你",
}

G["forever/class/warrior/haggards-weapons"] = {
	["At 10, {npc:1229}, the warrior trainer in {area:131}, sends you to {quest:1679} in {zone:1455}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} is the quickest stance (one fight in a tavern), with a Haggard's weapon after it."] = "10级时，{area:131}的战士训练师{npc:1229}会让你去{zone:1455}的{quest:1679}处。任何联盟战士都可以走三条路线之一，但不能同时走两条：10级时反正也要去{zone:1453}吗？{npc:5480}的{quest:1638}是最快的姿态任务（在酒馆里打一场），之后还能拿到哈加德的武器。",
	["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "10级时，{npc:252377}和训练师们站在{area:16638}西门旁。邪教徒{npc:257196}在{area:16629}拿着她家族的盾牌。",
	["At 10, {npc:3598}, the warrior trainer in {area:186}, or {npc:2151}, who patrols the road west of {area:186}, sends you to {quest:1684} on the {area:1660} in {zone:1457}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} teaches the same stance after one fight in a tavern."] = "10级时，{area:186}的战士训练师{npc:3598}，或在{area:186}以西路上巡逻的{npc:2151}，会让你去{zone:1457}的{area:1660}上找{quest:1684}。任何联盟战士都可以走三条路线之一，但不能同时走两条：10级时反正也要去{zone:1453}吗？{npc:5480}的{quest:1638}在酒馆里打一场后也能教同样的姿态。",
	["At 10, {npc:913}, the warrior trainer by the inn in {area:87}, sends you to {npc:6089} in {zone:1453}; {npc:5480}, the warrior trainer in {zone:1453}'s {object:2100}, offers it too."] = "10级时，{area:87}旅店旁的战士训练师{npc:913}会让你去{zone:1453}的{npc:6089}处；{zone:1453}中{object:2100}里的战士训练师{npc:5480}也提供这个任务。",
	["Back on the {area:1660}: {npc:4088} hands you the {item:6812}; {npc:6142} works on the far, south side of the same terrace, easy to miss."] = "回到{area:1660}：{npc:4088}交给你{item:6812}；{npc:6142}在同一平台的远端南侧工作，很容易错过。",
	["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:6090}'s road below still gives a weapon, once you reach {zone:1453}."] = "回到{area:16638}找{npc:252377}。她教你{spell:71}，并给你{item:275290}，一面配合该技能使用的盾牌。下面{npc:6090}的路线仍会给一件武器，等你到达{zone:1453}后。",
	["Back to {npc:6114} for {spell:71}, then to {quest:1680} at the {object:32372} in the middle of {zone:1455}."] = "回到{npc:6114}处学{spell:71}，然后去{zone:1455}中央{object:32372}处的{quest:1680}。",
	["Bartleby"] = "巴特比",
	["Elunite under {area:442}"] = "{area:442}下方的艾露恩矿石",
	["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "从{area:16638}向西北前往{area:16629}。{npc:257196}站在神殿通道的西侧，混在教派的守卫者、唤灵者和剑师中间：先一个一个拉掉他们，再动他。他掉落{item:263993}。",
	["Take the boat from {area:702} to {area:442}. The wreck lies underwater just south of {area:442}'s southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey {npc:6133} (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in."] = "从{area:702}坐船到{area:442}。残骸在水下，就在{area:442}南码头以南、米奈希尔船只停靠的地方。在残骸周围的海底打开艾露恩矿石箱，直到凑够八个：箱子分布在巨大的沉没海龟旁、靠近沙滩处和码头下方；每个箱子都有矿石，3-5分钟刷新。灰色的{npc:6133}（11级）在残骸中部漂游，必掉徽章：看到它就选中，这样浮上水面换气后还能找到它。注意呼吸；鲨鱼可能会加入。",
	["Warrior"] = "战士",
	["Zaal Stormshield"] = "扎尔·风盾",
	["from {npc:6093}"] = "来自{npc:6093}",
	["{item:263993}, from {npc:257196}"] = "{item:263993}，来自{npc:257196}",
	["{item:6782}, from {object:85563}"] = "{item:6782}，来自{object:85563}",
	["{item:6800}, from {object:85562}"] = "{item:6800}，来自{object:85562}",
	["{item:6808}, from Crates of Elunite"] = "{item:6808}，来自艾露恩矿石箱",
	["{item:6809}, from the {npc:6133}"] = "{item:6809}，来自{npc:6133}",
	["{npc:252377} in {area:16638}"] = "{area:16638}的{npc:252377}",
	["{npc:294}'s manor stands at the south-east edge of the {area:88} in eastern Elwynn, at the end of a short road that does not join the main one."] = "{npc:294}的庄园位于艾尔文森林东部{area:88}的东南边缘，在一条不与主路相连的小路尽头。",
	["{npc:6089} and {npc:6090} are in the Pig and Whistle tavern in {object:2100}; {npc:6090} is the drunk at the far end of the bar. {npc:6090} (level 10) hits harder than his level, so start at full health; he gives up at low health instead of dying. If he wins, he disappears for about three minutes: keep the quest and talk to him again when he is back. A Dwarf, Gnome or Night Elf who took {quest:1638} from {npc:5480} instead of their home road is led through {zone:1453} from here."] = "{npc:6089}和{npc:6090}在{object:2100}的猪与哨子酒馆里；{npc:6090}是酒吧最里端的醉汉。{npc:6090}（10级）攻击力超出其等级，所以满血开打；他残血时会认输而不是死亡。如果他赢了，他会消失约三分钟：留着任务，等他回来再谈。矮人、侏儒或暗夜精灵若从{npc:5480}处接了{quest:1638}而非本族路线，会从这里被引导穿过{zone:1453}。",
	["{npc:6093} (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops {item:6783}; open {object:85563} in the crates by him for {item:6782}. Jack returns 3 minutes after dying, the box 1 minute after opening."] = "{npc:6093}（11级）在艾尔文森林最东南角扎营。一名卫兵站在他旁边，迪菲亚和狼散布在营地周围（偶尔还有更稀有的卫兵）：一次清一个，然后杀杰克。他必掉{item:6783}；打开他旁边箱子里的{object:85563}可获得{item:6782}。杰克死后3分钟回来，箱子打开后1分钟刷新。",
	["{quest:1678} (level 11, a lone troll) waits at his hut on a hill south of {area:135}, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of {area:135} is the wrong one. He fights in {spell:71} and sunders your armor; {spell:6343} slows him. His head always drops; he returns about 8 minutes after dying."] = "{quest:1678}（11级，落单的巨魔）在{area:135}以南一座山丘上的小屋中等候，靠近山脉、在一段短斜坡顶端，周围没有其他巨魔；{area:135}前部的小屋不是他。他会切姿态{spell:71}并破你的甲；{spell:6343}能减速他。他的头必掉；死后约8分钟回来。",
	["{quest:1679} in {zone:1455}"] = "{zone:1455}的{quest:1679}",
	["{quest:1679} stands in the {object:32390} in the {object:32359}."] = "{quest:1679}在{object:32359}中的{object:32390}里。",
	["{quest:1681} lies in eastern {zone:1426}, below {area:212} on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. {object:85562} is in the basement of the southernmost house; {npc:6124} (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening."] = "{quest:1681}在{zone:1426}东部、{area:212}南侧下方。黑铁间谍（8-10级）沿途站着，彼此距离够远，可以一次拉一只。{object:85562}在最南边房屋的地下室里；{npc:6124}（11级）站在旁边，一看到你就冲过来。箱子里必有矿石，打开后15分钟刷新。",
	["{quest:1683} (level 10, a satyr) stands at a hidden moonwell up a hillside west of {area:186}. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying."] = "{quest:1683}（10级，萨特）站在{area:186}以西山坡上一处隐蔽的月亮井旁。小路很难发现：它从一处纳尔派营地后方开始，以之字形爬升，两旁立着灯柱。下面的熊怪可能成群出现。他的角必掉；死后5分钟回来。",
	["{quest:1684} in {zone:1457}"] = "{zone:1457}的{quest:1684}",
	["{quest:1684} stands on the {area:1660}."] = "{quest:1684}在{area:1660}上。",
	["{spell:71} and a Weapon (Alliance)"] = "{spell:71}与武器（联盟）",
	["{spell:71} at 10 and a one-hand weapon of your choice from {zone:1453}, {zone:1455} or {zone:1457}."] = "10级获得{spell:71}，并从{zone:1453}、{zone:1455}或{zone:1457}任选一件单手武器。",
}

G["forever/collectibles/pets/chicken-egg"] = {
	["Buy one {item:11109} (25 copper) from {npc:233} at his farm first: it is not a quest item, and the chicken stays friendly only for a short while."] = "先在他农场从{npc:233}处买一个{item:11109}（25铜）：它不是任务物品，而小鸡保持友善的时间很短。",
	["Target one of the chickens around Saldean's farm and type /chicken at it, again and again, until it offers {quest:3861}; this can take several minutes. Then /cheer at a chicken until it turns friendly (green) and hand in the feed; right-clicking a chicken before it is friendly attacks it. The chicken lays an egg on the ground: loot it for your {item:11110}."] = "选中萨尔丁农场周围的一只小鸡，反复对它输入 /chicken，直到它提供{quest:3861}；这可能需要好几分钟。然后对一只小鸡输入 /cheer，直到它变为友善（绿色），再交付饲料；在小鸡变得友善之前右键点击它会攻击它。小鸡会在地上下一个蛋：拾取它即可获得你的{item:11110}。",
}

G["forever/collectibles/pets/yarlyn-amberstill"] = {
	["{npc:1263} stands at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}, the ram breeder. Each rabbit crate costs 20s; the Arctic and Brown crates are new in Forever. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:1263}站在{area:803}，位于{area:131}以东、通往{zone:1432}的路上，旁边是公羊饲养员{npc:1261}。每个兔子笼售价20银；北极兔和棕兔笼是Forever新增的。每个宠物物品使用时都会教给对应的伙伴；之后目标仍保持勾选。",
}

G["forever/alliance/05-duskwood"] = {
	["Class trainer"] = "职业训练师",
	["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters.
Careful: A {npc:948} casts {spell:3428} as it dies, which brings extra adds."] = "{area:492}北半部的每个食尸鬼都可能掉落肋骨：食肉者、嚼骨者、瘟疫传播者和食脑者。
小心：一个{npc:948}死亡时会施放{spell:3428}，会带来额外的怪。",
	["Fly to {zone:1453}"] = "飞往{zone:1453}",
	["Follow the road south from {area:1002} into {area:10}; {area:42} lies on the east side of the forest."] = "从{area:1002}沿路向南进入{area:10}；{area:42}在森林东侧。",
	["Head back east along the road to the {area:245}."] = "沿路向东回到{area:245}。",
	["Head back east to {area:42}."] = "向东回到{area:42}。",
	["Head north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "穿过艾尔文森林向北到{zone:1453}；马迪亚斯·肖尔在{object:2100}的军情七处。",
	["Head west along the road once more."] = "再次沿路向西。",
	["Head west along the road out of {area:94} into {area:40}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "沿路向西离开{area:94}进入{area:40}。{npc:7024}在边界内侧的山丘上监视{npc:7053}的塔楼。守卫塔楼的{npc:7051}（23级）身上带着钥匙；克拉文的手记在塔顶的箱子里。",
	["Head west to the hermit once more."] = "再次向西去找隐士。",
	["Inside"] = "室内",
	["Nightbane Shadow Weaver"] = "夜行魔织影者",
	["No {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too.
{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "没有{item:4371}做{quest:174}？{npc:3133}在{npc:276}旁的房子里出售，存货有限；{area:150}的{npc:1448}也卖。
{npc:276}的房子在小镇东端。{npc:3133}在它旁边的房子里卖工程学商品。",
	["Pygmy Venom Web Spider"] = "小毒网蜘蛛",
	["Rabid Dire Wolf"] = "狂躁凶狼",
	["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders crawl east of the cemetery and drop the venom. Every ghoul of the cemetery's northern half can drop a fang.
Careful: Wolves and other spider types share the area along the {area:40} border, so you can easily pull several mobs at once."] = "狂躁凶狼在墓地和{npc:289}周围的森林游荡，饥饿凶狼在他东北的山丘。小毒网蜘蛛在墓地东边爬行，掉落毒液。墓地北半部的每个食尸鬼都可能掉落獠牙。
小心：狼和其他种类的蜘蛛共处{area:40}边界一带，很容易一次拉好几只怪。",
	["Rogue training"] = "潜行者训练",
