G["forever/alliance/30-40/06-badlands"] = {
	["Flesh Picker"] = "食腐者",
	["Fly to {area:150}"] = "飞往{area:150}",
	["Head back west to the road and follow it south out of {zone:1432} through the pass into the {area:3}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "回到西边的路上，沿路向南离开{zone:1432}，穿过山口进入{area:3}。{npc:2910}和{npc:2860}并排在挖掘场扎营。",
	["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "向东北前往废弃的挖掘场；补给箱就在那里的沙腮食人魔中间。",
	["Head north-east to the dwarven ruins in the north of the {area:3}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "向东北前往{area:3}北部的矮人废墟；箱子在暗炉矮人中间。附近的{npc:2745}是精英：离他远点。",
	["Head south to {area:345}."] = "向南前往{area:345}。",
	["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "向西进入{area:1878}；{npc:2921}在中间他的机器旁工作。",
	["Into {area:3}"] = "进入{area:3}",
	["Stonevault Bonesnapper"] = "石窟断骨者",
	["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east.
The battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.
The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}.
Careful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "沙腮食人魔就在山谷南边扎营；他们中任何一个都会掉落废料。秃鹫在东边的平原盘旋。
破烂的骷髅躺在石窟穴居人营地边缘；杀死阿格蒙德的凶手{quest:739}在断骨者中间走动。
次级岩石元素在{npc:2921}西边的{area:1878}游荡。
小心：沙腮领主是44-45级。他们会用{spell:5242}和{spell:1160}，生命值低于50%时会呼叫15码内的盟友支援。其中七个站在{area:340}以南约750码处。",
	["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "破烂的骷髅就在食人魔东边、石窟穴居人营地边缘；周围的断骨者和萨满掉落碎片。塞尔杜林坐在更南边被毁的营地旁。",
	["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit.
Careful: Most of the mobs here walk patrol routes, so you can easily pull extra mobs."] = "恶魔聚集在{zone:1443}南部的{area:602}：地狱犬（法力吞噬者、法师猎手和魔网猎手）、虚空女妖和虚空姐妹，以及坑周围的末日守望者队长。
小心：这里大多数怪物走巡逻路线，很容易多拉怪。",
	["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "飞行管理员站在{area:514}的门口；{npc:5083}和{npc:4964}在城堡内。",
	["The next guide starts in Theramore."] = "下一份指南从塞拉摩开始。",
	["The skeleton's next task, {quest:739}, waits until the later {area:3} guide at 43."] = "骷髅的下一个任务{quest:739}要等到后面43级的{area:3}指南。",
	["To {area:2101}"] = "前往{area:2101}",
