G["forever/alliance/nightelf/01-teldrassil"] = {
	["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "在{npc:265811}的营火旁坐下（/sit），直到获得{spell:1229451}",
	["Back out of the city gate and east along the road: {quest:1683} stands south of it, by {area:736}. Bring his horn back to {quest:1684}."] = "出城门后沿路向东：{quest:1683}站在路南、{area:736}旁。把他的号角带回去交给{quest:1684}。",
	["Below ground"] = "地下",
	["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}。{npc:11802}在{area:2361}；{quest:5929}位于西北的树林里。然后{area:2361}的{npc:11800}会把德鲁伊直接送到{area:702}，无需飞行路线。{npc:11802}站在他那栋楼的楼上：从里面上楼，箭头分不清楼层。",
	["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "魔锥草散布在{area:186}和{npc:2150}周围的所有树下：向东的路上顺手采集，前往{npc:7234}时交给{npc:2150}。",
	["From {area:17203}, head through the city gates into {zone:1429} and follow the road west to {zone:1436}."] = "从{area:17203}出发，穿过城门进入{zone:1429}，沿路向西到{zone:1436}。",
	["Gnarlpine Ambusher"] = "瘤背伏击者",
	["Gnarlpine Mystic"] = "瘤背秘法师",
	["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.
Careful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "瘤背秘法师和{npc:7234}在{area:260}东北扎营。{npc:7234}掉落{item:8049}：打开取宝石。
注意：{npc:7234}在营火旁等候，身边围着秘法师，所以很难在不引到增援的情况下拉他。",
	["Into {zone:1457}"] = "进入{zone:1457}",
	["Learn the flight path from {npc:3841} where you land. {npc:4200}'s fish stall is just north of her, by the docks.
The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "降落后先找{npc:3841}学习飞行路线。{npc:4200}的鱼摊就在她北边、码头旁。
船停在村子西边。飞行管理员站在旅店南边的山丘上；任务发布者分散在主街上。",
	["Mangy Nightsaber"] = "癞皮夜刃豹",
	["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside."] = "癞皮夜刃豹和蓟野猪在{area:256}以北游荡，就在去洞穴的路上。{npc:1994}坐在洞穴深处。",
	["Nightsaber Stalker"] = "夜刃豹潜行者",
	["Nightsabers, Strigid Owls and Webwood Lurkers roam all around {area:186} and along the road east; the lurkers also drop the recipe's spider legs. The moonwell is at the west edge of {area:260}."] = "夜刃豹、夜枭和蛛网潜伏者遍布{area:186}周围以及东边的路上；潜伏者还会掉落配方所需的蜘蛛腿。月亮井在{area:260}的西缘。",
	["North from the lake to {npc:2150}, on the road back to {area:186}."] = "从湖边向北到{npc:2150}，就在回{area:186}的路上。",
	["Portal to {quest:940}"] = "通往{quest:940}的传送门",
	["Rageclaw"] = "怒爪",
	["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "在星风村西南、{npc:2150}以南。{npc:2080}在岸边照料他的树苗；鞭笞幼芽和小树人围着他游荡，{quest:919}就长在它们中间。",
	["Strigid Screecher"] = "夜枭尖啸者",
	["The Bloodfeather harpies nest on the slopes west and north of the glade.
Careful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them."] = "血羽鹰身人在林间空地以西和以北的山坡筑巢。
注意：鹰身人站得很密集，所以常会有额外的加入战斗。施法者混在它们中间。",
	["The WANTED poster outside the inn"] = "旅店外的通缉令",
	["The moonwell sits north of {area:256}."] = "月亮井位于{area:256}以北。",
	["The trainers stand upstairs inside {area:256}, along the ramp that winds up the tree: {npc:3593} and {npc:3594} on the first level, {npc:3595} above them, {npc:3596} and {npc:3597} at the top. The arrow cannot tell the levels apart."] = "训练师们站在{area:256}内的楼上，沿绕着树干盘旋而上的坡道分布：{npc:3593}和{npc:3594}在第一层，{npc:3595}在他们上方，{npc:3596}和{npc:3597}在顶层。箭头分不清楼层。",
	["Thistle Boar"] = "蓟野猪",
	["Tide Crawlers scuttle along the shore below the village; {object:17182} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "潮汐爬行者沿着村子下方的海岸爬行；{object:17182}立在码头正南的海滩上。黑海岸长尾鲨在浅水中游动。{object:175207}躺在村子正南的海岸上。",
	["Upstairs"] = "楼上",
	["Ursal the Mauler"] = "重击者乌尔萨",
	["Use the {item:18152} at the moonwell"] = "在月亮井旁使用{item:18152}",
	["Walk south along the west side of the island. Ursal prowls the far south, below the {area:478}.
Careful: Gnarlpine of roughly level 9-12 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal."] = "沿岛屿西侧向南走。乌尔萨在遥远的南方、{area:478}下方徘徊。
注意：约9-12级的瘤背熊怪挤在营地里，站位很密，很容易一次拉到好几只。先一只只解决它们，再去对付乌尔萨。",
	["Webwood Lurker"] = "蛛网潜伏者",
	["Webwood Spiders; below ground"] = "蛛网蜘蛛；地下",
	["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "顺路：向{npc:11866}（{area:1660}，10银）学习法杖；猎人的近战武器主要看属性，双手武器提供的属性最多。",
	["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "顺路：向{npc:11866}（{area:1660}，10银）学习法杖；升级期间法杖提供的法术属性比单手武器多。",
	["Young Nightsaber"] = "年幼的夜刃豹",
	["Young Thistle Boar"] = "年幼的蓟野猪",
	["the same {object:673378}: Fandral in {zone:1457} takes it"] = "同一个{object:673378}：{zone:1457}的范达尔会收下它",
	["{area:188}: kill these as you meet them"] = "{area:188}：遇到就杀",
	["{item:10639} along the way to {area:256}"] = "{item:10639}，在去{area:256}的路上",
	["{item:10639} on the way"] = "{item:10639}，途中",
	["{item:8049}, from {npc:7234}"] = "{item:8049}，来自{npc:7234}",
	["{npc:10216}, on the pier: only with {skill:356}"] = "{npc:10216}，在码头上：需要{skill:356}",
	["{npc:1984} along the way to Back at {area:256}"] = "{npc:1984}，在回{area:256}的路上",
	["{npc:1984} on the way"] = "{npc:1984}，途中",
	["{npc:2038}; below ground"] = "{npc:2038}；地下",
	["{npc:2107} stands upstairs in a house in the village, east of the moonwell: go up inside, the arrow cannot tell the floors apart. {object:126158} is in the house on the hill at the east end of the village."] = "{npc:2107}站在村子东边、月亮井以东一栋房子的楼上：从里面上楼，箭头分不清楼层。{object:126158}在村子东端山丘上的房子里。",
	["{npc:3567}, back in {area:186}; upstairs"] = "{npc:3567}，回到{area:186}；楼上",
	["{npc:3567}, upstairs"] = "{npc:3567}，楼上",
	["{npc:3593}, the warrior trainer; inside"] = "{npc:3593}，战士训练师；室内",
	["{npc:3595}: in at the tree's front entrance and up the ramp; upstairs"] = "{npc:3595}：从树的前门进入，沿坡道上行；楼上",
	["{npc:3598}, the warrior trainer: {quest:1684} in {zone:1457} takes it"] = "{npc:3598}，战士训练师：{zone:1457}的{quest:1684}会收下它",
	["{npc:3600}, inside"] = "{npc:3600}，室内",
	["{npc:3608}, upstairs"] = "{npc:3608}，楼上",
	["{npc:3649}, north end of the village"] = "{npc:3649}，村子北端",
	["{npc:4088}, on the {area:1660}: {spell:71}"] = "{npc:4088}，在{area:1660}上：{spell:71}",
	["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{npc:4146}，在{area:1658}内：{spell:5149}",
	["{npc:6094} takes a {item:159} with the fronds and the vial: if you drank yours, buy another from {npc:6736} in this inn before you hand in."] = "{npc:6094}要一份{item:159}，连同叶子和药瓶一起：如果你已经喝掉了自己的，就在交任务前到这间旅店找{npc:6736}再买一份。",
	["{npc:6094}, inside"] = "{npc:6094}，室内",
	["{npc:6286}, south of the inn: Camping 101 asks you to learn it"] = "{npc:6286}，旅店以南：《露营入门》要求你学会它",
	["{npc:7317}, below ground"] = "{npc:7317}，地下",
	["{npc:7318}, in the den; walks around {area:736}: look inside the circle on the map"] = "{npc:7318}，在洞穴里；在{area:736}一带走动：看地图上的圆圈内",
	["{npc:8584} is a little further north-west. {quest:3522} lasts five minutes: fill the phial and go straight on to him."] = "{npc:8584}再往西北一点。{quest:3522}持续五分钟：装满小瓶后直接去找他。",
	["{npc:8584} waits in the trees west of the cave mouth."] = "{npc:8584}在洞口以西的树林里等候。",
	["{object:126158}; inside"] = "{object:126158}；室内",
	["{object:654846}, upstairs"] = "{object:654846}，楼上",
	["{quest:1684} stands on the {area:1660}, just inside the city."] = "{quest:1684}站在{area:1660}上，就在城内。",
	["{quest:940}: kill these as you meet them"] = "{quest:940}：遇到就杀",
	["{quest:97236}; below ground"] = "{quest:97236}；地下",
	["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979}：施放{spell:1259799}并影遁，然后把它交还给{npc:3595}",
}

G["forever/class/hunter/taming-the-beast-alliance"] = {
	["At 10 go to {npc:1231}, the hunter trainer at the smithy in {area:131}. The Hunter's Path from {npc:5116} in {zone:1455}, {npc:11807} north-west of {area:131} or {npc:5515} in {zone:1453} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "10级时去找{npc:1231}，{area:131}铁匠铺的猎人训练师。来自{zone:1455}的{npc:5116}、{area:131}西北的{npc:11807}或{zone:1453}的{npc:5515}的“猎手之路”也会指引到这里，可得到少量经验；它只是指路任务。10级时改去艾尔文森林？{area:87}的{npc:251507}任务链教的内容一样。",
	["At 10 go to {npc:251507}, the hunter trainer who stands with the other trainers by the Lion's Pride Inn in {area:87}; {npc:258930}, the pet trainer, is beside her. Skyborne: this is for one who left {zone:2521} without taming; it teaches the same."] = "10级时去找{npc:251507}，她和其它训练师一起站在{area:87}的狮王之傲旅店旁；宠物训练师{npc:258930}就在她身边。天裔：这是给没在{zone:2521}完成驯服就离开的人准备的；教的内容一样。",
	["At 10 go to {npc:3601}, the hunter trainer in {area:186}. The Hunter's Path from {npc:3596} at {area:256}, {npc:4146} in {zone:1457}, {npc:5515} in {zone:1453}, {npc:5116} in {zone:1455} or {npc:1231} in {area:131} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "10级时去找{area:186}的猎人训练师{npc:3601}。来自{area:256}的{npc:3596}、{zone:1457}的{npc:4146}、{zone:1453}的{npc:5515}、{zone:1455}的{npc:5116}或{area:131}的{npc:1231}的“猎手之路”也会指引到这里，可得到少量经验；它只是指路任务。10级时改去艾尔文森林？{area:87}的{npc:251507}任务链教的内容一样。",
	["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "10级时，{zone:2521}上的猎人训练师{npc:254084}可能会用{quest:94007}派你前往{area:16638}。这只是指路任务：如果你已经在{area:16638}，就跳过它。",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of {area:87}, east of {area:18}."] = "先解散野猪（右键点击宠物头像，{spell:2641}）：放生的练习宠物可能会反咬你。灰森林狼（7-8级）在{area:87}以东、{area:18}以东的树林里奔跑。",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Snow Leopards (level 7-8) prowl the slopes south-east of {area:131}, more north-west and west of it; the smaller Juvenile Snow Leopards do not count."] = "先解散野猪（右键点击宠物头像，{spell:2641}）：放生的练习宠物可能会反咬你。雪豹（7-8级）在{area:131}东南的山坡徘徊，西北和西边也有更多；体型较小的幼年雪豹不算。",
	["Dismiss the cat. Strigid Screechers (level 7-8), owls, perch in the woods south, south-west and west of {area:186}."] = "解散猫。夜枭尖啸者（7-8级，属猫头鹰）栖息在{area:186}以南、西南和西边的树林。",
	["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "先解散爬行者（右键点击宠物头像，{spell:2641}）。暴躁风行者（Ornery Galestrider）在{area:16626}吃草，那片田野就在{area:16638}西面和西南面不远处。",
	["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "解散风行者。鹫龙首领在同一片{area:16626}狩猎，位置稍偏南。",
	["Dismiss the leopard. Ice Claw Bears (level 7-8) roam the hills around {area:131}, many south-east of it and more north-west toward {area:77}; their {spell:3130} hits hard, so start at full health."] = "解散豹。冰爪熊（7-8级）在{area:131}周围的山丘游荡，很多在东南，西北靠{area:77}方向更多；它们的{spell:3130}很疼，所以满血开始。",
	["Dismiss the spider first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Nightsaber Stalkers (level 7-8) lie on the hillside south of {area:259}, south of {area:186}; the plain Nightsabers by the village do not count."] = "先解散蜘蛛（右键点击宠物头像，{spell:2641}）：放生的练习宠物可能会反咬你。夜刃豹潜行者（7-8级）在{area:259}以南、{area:186}以南的山坡上；村子旁的普通夜刃豹不算。",
	["Dismiss the wolf. Young Forest Bears (level 8-9) roam the woods just south of {area:87}, with more south-west and south-east of town."] = "解散狼。幼森林熊（8-9级）在{area:87}正南的树林里游荡，镇子西南和东南也有更多。",
	["Gray Forest Wolf"] = "灰森林狼",
	["Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."] = "快乐值：宠物框上的表情。不快乐的宠物只能造成四分之三的伤害，快乐的则多四分之一。快乐值会缓慢下降，宠物死亡时下降更快；宠物不快乐太久可能会跑掉。",
	["Hunter"] = "猎人",
	["Ice Claw Bear"] = "冰爪熊",
	["Large Crag Boar"] = "大型峭壁野猪",
	["Large Crag Boars (level 6-7) root around the fields west, south and north-west of {area:131} and respawn every 3 minutes. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, being out of range or anyone else's help breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from {npc:1231}. The boars use {spell:6268} from 25 yards, so start with the rod, not {spell:75}. Keep each rod: it goes back to {npc:1231}."] = "大型峭壁野猪（6-7级）在{area:131}以西、以南和西北的田野里拱土，每3分钟刷新。魔杖用法：选中一只活着的野兽，使用{item:15908}，在整个引导期间站着不动、任由它攻击你。移动、还手、超出范围或他人帮忙都会中断，并消耗魔杖少量充能之一；若充能耗尽，就摧毁魔杖、放弃任务并回去找{npc:1231}再接。野猪会从25码外使用{spell:6268}，所以先用魔杖，别用{spell:75}。每根魔杖都留着：要还给{npc:1231}。",
	["Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one)."] = "忠诚度随时间与击杀增长。每提升一级忠诚度都会提高你在{spell:5149}中可用的训练点数（宠物等级乘以忠诚等级再减一）。",
	["Near {area:131}: Snow Leopards (cats, level 7-8) prowl all over {zone:1426}, Scarred Crag Boars (9-10) its east toward {zone:1432}; at 10-11, Mountain Boars roam western {zone:1432}."] = "{area:131}附近：雪豹（猫科，7-8级）在{zone:1426}四处徘徊，伤痕峭壁野猪（9-10级）在其东部靠{zone:1432}方向；10-11级时，山地野猪在{zone:1432}西部游荡。",
	["Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2521}."] = "{area:16638}附近：鹫龙首领（10级，也就是你最后一次练习驯服的野兽）在{area:16626}狩猎；尖啸迅猛龙族长（迅猛龙，9级）在{area:16638}以西筑巢；暗风乌瑟拉斯（熊，10-11级）在{zone:2521}北部游荡。",
	["Near {area:186}: Elder Nightsabers (cats, level 8-9) and Feral Nightsabers (cats, 10-11) prowl the woods of north-western {zone:1438}."] = "{area:186}附近：老年夜刃豹（猫科，8-9级）和野性夜刃豹（猫科，10-11级）在{zone:1438}西北部的树林里徘徊。",
	["Near {area:87} there are no cats: Prowlers (wolves, level 9-10) roam eastern Elwynn, Longsnouts (boars, 10-11) its far south-west by the {zone:1436} border; at 12-13, Young Goretusks (boars) graze the fields of northern {zone:1436}."] = "{area:87}附近没有猫科：徘徊者（狼，9-10级）在艾尔文森林东部游荡，长鼻野猪（野猪，10-11级）在最西南靠{zone:1436}边界一带；12-13级时，幼年血牙野猪（野猪）在{zone:1436}北部的田野吃草。",
	["Nightsaber Stalker"] = "夜刃豹潜行者",
	["Ornery Galestrider"] = "暴躁风行者",
	["Pet trainers sell {spell:1853} ranks and resistances. Alliance: {npc:258930} in {area:87}, {npc:2879} by the hunter trainers in {zone:1453}'s {object:28027}, {npc:2878} in {area:131}, {npc:10090} in {zone:1455}'s {object:32390}, Keldas in {area:186}, Silvaria in {zone:1457}' Cenarion Enclave, {npc:254411} in {area:16638}."] = "宠物训练师出售{spell:1853}的各级和抗性。联盟：{area:87}的{npc:258930}、{zone:1453}的{object:28027}里猎人训练师旁的{npc:2879}、{area:131}的{npc:2878}、{zone:1455}的{object:32390}里的{npc:10090}、{area:186}的凯尔达斯、{zone:1457}塞纳里奥区的西尔瓦里娅、{area:16638}的{npc:254411}。",
	["Rockhide Boar"] = "石皮野猪",
	["Rockhide Boars (level 7-8) graze in three herds south and south-east of {area:87}, toward the {area:64}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again. The boars use {spell:6268}, so start with the rod, not {spell:75}. Killing a boar does not count. Keep each rod: it goes back to Josephine. A Dwarf or Night Elf who took Josephine's rod instead of their home trainer's is led through {area:87} from here."] = "石皮野猪（7-8级）在{area:87}以南和东南、靠{area:64}方向分三群吃草。魔杖用法：选中一只活着的野兽，使用{item:15908}，在整个引导期间站着不动、任由它攻击你。移动、还手、他人治疗或任何人攻击该野兽都会中断，并消耗魔杖少量充能之一；若充能耗尽，就摧毁魔杖、放弃任务并再接一次。野猪会使用{spell:6268}，所以先用魔杖，别用{spell:75}。杀死野猪不算数。每根魔杖都留着：要还给约瑟芬。矮人或暗夜精灵拿了约瑟芬的魔杖而不是家乡训练师的，会从这里被引导走完{area:87}。",
	["Snow Leopard"] = "雪豹",
	["Strigid Screecher"] = "夜枭尖啸者",
	["Take the road west from {area:186} to {zone:1457}. {npc:4146} stands inside the {area:1658} with the hunter trainers; Silvaria, the pet trainer, is up the ramp next to her."] = "从{area:186}沿路向西到{zone:1457}。{npc:4146}和猎人训练师们站在{area:1658}内；宠物训练师西尔瓦里娅在她旁边、坡道上方。",
	["Tame a beast of your level to keep"] = "驯服一只与你等级相当的野兽作为永久宠物",
	["Tame {npc:1922}"] = "驯服{npc:1922}",
	["Tame {npc:250874}"] = "驯服{npc:250874}",
	["Tame {npc:251707}"] = "驯服{npc:251707}",
	["Tame {npc:254588}"] = "驯服{npc:254588}",
	["Tame {npc:524}"] = "驯服{npc:524}",
	["Tame {npc:822}"] = "驯服{npc:822}",
	["Use the {item:15908} on a living alpha"] = "对活着的首领使用{item:15908}",
	["Use the {item:15908} on a living bear"] = "对活着的熊使用{item:15908}",
	["Use the {item:15908} on a living boar"] = "对活着的野猪使用{item:15908}",
	["Use the {item:15908} on a living crawler"] = "对活着的爬行者使用{item:15908}",
	["Use the {item:15908} on a living galestrider"] = "对活着的风行者使用{item:15908}",
	["Use the {item:15908} on a living leopard"] = "对活着的豹使用{item:15908}",
	["Use the {item:15908} on a living owl"] = "对活着的猫头鹰使用{item:15908}",
	["Use the {item:15908} on a living spider"] = "对活着的蜘蛛使用{item:15908}",
	["Use the {item:15908} on a living stalker"] = "对活着的潜伏者使用{item:15908}",
	["Use the {item:15908} on a living wolf"] = "对活着的狼使用{item:15908}",
	["Vuldren Alpha"] = "鹫龙首领",
	["Webwood Lurker"] = "蛛网潜伏者",
	["Webwood Lurkers (level 5-6) creep through the woods just north-east, south-west and east of {area:186}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you; moving, attacking it or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). Their {spell:1265843} roots you but does not break the channel if you keep still. Keep each rod: it goes back to {npc:3601}."] = "蛛网潜伏者（5-6级）在{area:186}东北、西南和东边的树林里爬行。魔杖用法：选中一只活着的野兽，使用{item:15908}，在整个引导期间站着不动、任由它攻击你；移动、攻击它或他人帮忙都会中断，并消耗魔杖少量充能之一（充能耗尽：摧毁魔杖，放弃任务，再接一次）。它们的{spell:1265843}会定住你，但只要你保持不动就不会打断引导。每根魔杖都留着：要还给{npc:3601}。",
	["Windsong Crawler"] = "鸣风爬行者",
	["Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of {area:16638}, among the crabs. How the rod works: target a living crawler, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges. Killing one does not count. Keep each rod: it goes back to {npc:252389}."] = "鸣风爬行者只生活在有水的地方：最近的一群在{area:16638}西南面的岸边，混在螃蟹之间。魔杖用法：选中一只活着的爬行者，使用{item:15908}，在整个引导期间站着不动、任由它攻击你；移动、还手或他人帮忙都会中断，并消耗魔杖少量充能之一。杀死它不算数。每根魔杖都留着：要还给{npc:252389}。",
	["Young Forest Bear"] = "幼森林熊",
	["Your first pet"] = "你的第一只宠物",
	["Your own pet at 10: three practice tames with a {item:15908} teach {spell:1515}, then {spell:5149}."] = "10级时的正式宠物：用{item:15908}完成三次练习驯服后，就学会{spell:1515}，然后是{spell:5149}。",
	["{npc:10090} in {zone:1455}"] = "{npc:10090}，在{zone:1455}",
	["{npc:10090}, the pet trainer, stands in the {object:32390} in {zone:1455}'s {object:32359}, by the hunter trainers."] = "{npc:10090}，宠物训练师，站在{zone:1455}的{object:32359}里的{object:32390}内，就在猎人训练师旁。",
	["{npc:1231} in {area:131}"] = "{npc:1231}，在{area:131}",
	["{npc:1231}: the first {item:15908}"] = "{npc:1231}：第一根{item:15908}",
	["{npc:251507} in {area:87}"] = "{npc:251507}，在{area:87}",
	["{npc:251507}: the first {item:15908}"] = "{npc:251507}：第一根{item:15908}",
	["{npc:252389} in {area:16638}"] = "{npc:252389}，在{area:16638}",
	["{npc:252389} stands with the trainers by {area:16638}'s west gate, {npc:254411} beside her."] = "{npc:252389}和训练师们一起站在{area:16638}西门旁，{npc:254411}就在她身边。",
	["{npc:252389}: the first {item:15908}"] = "{npc:252389}：第一根{item:15908}",
	["{npc:254411}, beside her: {spell:5149}"] = "她身边的{npc:254411}：{spell:5149}",
	["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}，在她身边：{spell:5149}",
	["{npc:3601} in {area:186}"] = "{npc:3601}，在{area:186}",
	["{npc:3601}: the first {item:15908}"] = "{npc:3601}：第一根{item:15908}",
	["{npc:4146} in {zone:1457}"] = "{npc:4146}，在{zone:1457}",
	["{quest:6063} (Alliance)"] = "{quest:6063}（联盟）",
	["{spell:1515} works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and {spell:17253}) and a boar takes more punishment."] = "{spell:1515}的用法和魔杖一样：目标须是与你同级或更低级的野兽，引导期间不能移动，野兽会一直攻击你。宠物会保持你驯服它时的等级，并随你一起升级；它永远不会高于你的等级，所以抓一只等级接近你的。在Forever上每个科系都有自己的技能（比如野猪的冲锋）。练级时，猫科伤害最高（爪击与{spell:17253}），野猪则更耐打。",
	["{spell:1584}: open your spellbook, cast {spell:1584} and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Toddrick the butcher in {area:87}, Jaeana in {zone:1457} and the innkeepers on {zone:2521} sell meat; the innkeepers of {area:131} and {area:186} sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat."] = "{spell:1584}：打开法术书，施放{spell:1584}，然后点击一份你宠物科系会吃的食物（宠物提示里会列出：猫科吃肉和鱼，野猪几乎什么都吃）。从野兽身上拾取的生肉也算。购买：{area:87}的屠夫托德里克、{zone:1457}的贾安娜和{zone:2521}上的旅店老板卖肉；{area:131}和{area:186}的旅店老板卖面包。食物等级接近宠物等级时它最快乐；食物低太多只能得到大约一半效果。战斗中不能喂食。",
	["{spell:5149} (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Erma in {area:87}, {npc:9980} in {area:131}, Seriadne in {area:186}, {npc:265756} on {zone:2521}), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with {spell:5149}. A pet holds four active abilities at most."] = "{spell:5149}（法术书，通用页）会把你已学会的技能教给当前宠物。要学新技能或更高等级：把宠物寄放在兽栏管理员处（{area:87}的厄玛、{area:131}的{npc:9980}、{area:186}的塞丽亚德妮、{zone:2521}上的{npc:265756}），驯服一只拥有该技能的野兽（它的宠物法术书页会显示它会什么），在战斗中反复使用该技能直到游戏提示你已学会，然后接回自己的宠物并用{spell:5149}教它。宠物最多同时拥有四个主动技能。",
	["{spell:883}, {spell:2641} and {spell:982} are in your spellbook now; {spell:136} comes from your trainer at 12. A dead pet needs {spell:982}; one that is away more than about 100 yards is dismissed and comes back with {spell:883}."] = "{spell:883}、{spell:2641}和{spell:982}现在已在你的法术书里；{spell:136}会在12级时由训练师教你。死掉的宠物需要{spell:982}；离你超过约100码的宠物会被解散，用{spell:883}召回。",
}

G["forever/class/shaman/call-of-water-alliance"] = {
	["At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}."] = "20级时，{zone:1455}的{object:32362}中的萨满训练师{npc:258098}派你去找{zone:1432}的{npc:258043}。",
	["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "带着{item:7810}回到{area:146}旁的{npc:258043}处。他会交给你{item:6637}和{item:7811}：两样都留着，去{zone:1436}要用。",
	["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "带着{item:7813}回到{npc:258043}处。把{item:5177}永久留在背包里：每个水图腾都要用它。",
	["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "在{npc:258203}洞穴下方瀑布的底部、淡水与咸水交汇处，装满{item:265732}。{object:147516}矮人在瀑布附近游荡。",
	["Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}."] = "飞往{area:108}，再向南到{area:20}：{area:919}和{object:619896}就在它北边。在神龛旁喝下{item:6637}，就能看到{npc:5894}（22级，会施放{spell:8056}和{spell:122}；只有一个刷新点，被杀后三分钟回来），击败它拿到护腕（必掉），然后把护腕和{item:7811}放到{object:619896}上（结束任务的是这一步，不是{npc:258043}）。再次点击神龛：{npc:5895}会浮现在旁边；离开前先和它交谈（如果它消失了，就放弃任务，在神龛处重新接取）。它会给你{item:7813}。",
	["Lost the {quest:94616}?"] = "把{quest:94616}弄丢了？",
	["Only if the {quest:94616} is gone from your bags: {npc:258043} gives you another before you leave for {zone:1436}."] = "只有当{quest:94616}从背包里消失时才需要：出发去{zone:1436}前，{npc:258043}会再给你一份。",
	["Shaman"] = "萨满",
	["Take the boat from {area:150} to {area:442} (it stops in {area:271} on the way), then fly or walk south through {zone:1439} to {area:415} in {zone:1440}. Fill the {item:265772} in the lake around the town, then the boat back to Menethil."] = "从{area:150}坐船到{area:442}（途中会停靠{area:271}），然后向南飞或步行穿过{zone:1439}，到{zone:1440}的{area:415}。在城镇周围的湖里装满{item:265772}，再坐船回米奈希尔。",
	["{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one."] = "{area:71}从赤脊山东部{area:68}中涌出（从{zone:1455}飞往{area:69}）。在它们脚下、鱼人夜行者聚集的地方装满{item:265747}；先把鱼人从那里引开。如果皮囊在没有计数的情况下消失，就放弃任务，回去找{npc:258203}再接一次，拿个新的。",
	["{npc:258043}'s burrow hut stands on the north-western shore of the loch, below {area:146}, north of {area:144}."] = "{npc:258043}的洞穴小屋位于湖的西北岸，{area:146}下方、{area:144}以北。",
	["{npc:258043}: a new {quest:94616}"] = "{npc:258043}：新的{quest:94616}",
	["{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}, east of {area:836}: not in a town. Through the Algaz tunnel north of {zone:1432}, then east off the road."] = "{npc:258203}的家人住在{zone:1437}南部瀑布下方的洞穴里，{area:836}以东：不在镇上。穿过{zone:1432}以北的阿尔加兹隧道，然后离开道路向东走。",
}

G["forever/collectibles/mounts/alliance/paladin-charger"] = {
	["An {item:12800} comes from Thorium veins and obsidian, about one vein in a hundred; a {item:18335} drops rarely from elites of level 59 and up (Revanchion and {npc:14695} about one kill in nine and one in a hundred). The Auction House is the usual source of both."] = "一个{item:12800}来自瑟银矿脉和黑曜石，大约每一百个矿脉出一个；{item:18335}由59级以上精英稀有掉落（雷万奇恩和{npc:14695}大约九次击杀出一次、每一百次出一次）。两者通常都在拍卖行买。",
	["Arcanite Bars x6: an alchemist, or the Trade District Auction House"] = "奥金锭 x6：找炼金师，或去贸易区拍卖行",
	["Bring the materials and 150 gold, taken at the hand-in. {npc:1416} walks to his forge and hands you the {item:18753}."] = "带上材料，外加150金币，交任务时收取。{npc:1416}会走到他的锻造炉旁，把{item:18753}交给你。",
	["Dire Maul West's door"] = "厄运之槌西区的门",
	["Lord Grayson blesses the censer into the {item:18752} for {area:2627}."] = "格雷森领主把香炉祝福成{item:18752}，用于{area:2627}。",
	["Lord Grayson hands you {item:18804}: open it for the {item:18746} and the {item:18792}. Keep both."] = "格雷森领主交给你{item:18804}：打开它，取出{item:18746}和{item:18792}。两样都留着。",
	["Lord Grayson keeps the barding for now: you get it back with the next quest."] = "格雷森领主暂时保留马铠：下一个任务会还给你。",
	["Lord Grayson takes the censer back."] = "格雷森领主收回了香炉。",
	["Paladin"] = "圣骑士",
	["Stratholme Supply Crates, inside"] = "斯坦索姆补给箱，室内",
	["Tendris Warpwood"] = "坦德里斯·曲木",
	["Terrordale Spirit"] = "恐惧谷幽灵",
	["Terrordale Spirits x25"] = "恐惧谷幽灵×25",
	["The {spell:23214} chain is long: {area:2279}, Dire Maul West and {area:2057} with a group, 350 gold in donations, and materials worth several hundred more (6 Arcanite Bars, 40 {item:14047}, 10 {item:8836}, two diamonds). Start saving early. Lord Grayson stands in the Cathedral of Light, {npc:6171} nearby."] = "{spell:23214}的任务链很长：要组队去{area:2279}、厄运之槌西区和{area:2057}，捐款350金币，材料还值好几百金（6块奥金锭、40个{item:14047}、10个{item:8836}、两颗钻石）。尽早开始攒钱。格雷森领主站在光明大教堂里，{npc:6171}就在旁边。",
	["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}; the door needs the {item:13704} (The Key to {area:2057}). Clear the {object:179746}, Rattlegore's room in the basement, then use the {item:18746} at its centre. Four waves of spirits come, each ending with an Aspect: players judge them with {spell:1105}, Justice, Righteousness and then Light, which stuns them. {npc:14516} (level 62 elite) comes after the last; he mind-controls players. Loot the {item:18749}, use it inside the Ossuary to redeem it, and give it and the {item:18792} to {npc:14568}. If the group wipes, the gates lock and the scryer is gone: abandon the quest and take it again from Lord Grayson for a new satchel. A group of five at 60. Again Into the {object:179746}, after the mount, lets you fight him again."] = "{area:2057}位于{area:2298}下方，那是{zone:1422}东南的岛上城镇；进门需要{item:13704}（通往{area:2057}的钥匙）。清空{object:179746}，也就是地下室的响骨房间，然后在房间中央使用{item:18746}。会来四波幽灵，每波最后都有一个化身：玩家依次用{spell:1105}、正义、公正和光明审判它们，光明会击晕它们。最后一波之后{npc:14516}（62级精英）会出现；他会精神控制玩家。拾取{item:18749}，在藏骨堂里使用以救赎它，然后把它和{item:18792}交给{npc:14568}。如果队伍团灭，大门会锁上，占卜镜也消失了：放弃任务，回去找格雷森领主再接一次，拿个新背包。需要5人队，60级。拿到坐骑后再进一次{object:179746}，可以再和他打一场。",
	["{area:2279} is a dungeon for a group of five at 58-60, at the north end of the {zone:1423}. Stratholme Supply Crates along the streets of both halves hold the Holy Water, one to three each; they come back after three minutes. Some crates let out a swarm of plagued rats or maggots: be ready. The main gate (the Scarlet half) needs no key."] = "{area:2279}是供58-60级五人小队进入的地下城，位于{zone:1423}北端。两半城区街道旁的斯坦索姆补给箱里装着圣水，每个一到三份；三分钟后恢复。有些箱子会放出一群瘟疫鼠或蛆虫：做好准备。正门（血色区那一半）不需要钥匙。",
	["{area:2577} lies in central {zone:1444}. From the gate at the foot of the ruins, walk up through the outer courtyards to the West wing's door at their north end; it needs a {item:18249} (from Pusillin in Dire Maul East) or a rogue's lockpicking. {npc:11489} (level 60 elite) stands at the far end of the West wing's first courtyard. Once attacked he calls every {npc:11459} still alive in the courtyard: kill them first. His death frees the {quest:7643}: talk to it to give it the horse feed and the {item:18753}, and it blesses the barding. A group of five at 60."] = "{area:2577}位于{zone:1444}中部。从废墟脚下的入口进去，穿过外围庭院，走到北端西翼的门；门需要{item:18249}（来自厄运之槌东区的普希林），或者找盗贼开锁。{npc:11489}（60级精英）站在西翼第一个庭院的尽头。一旦被攻击，他会召唤庭院里所有还活着的{npc:11459}：先杀掉它们。他死后会释放{quest:7643}：与它交谈，给它马饲料和{item:18753}，它就会祝福马铠。需要5人队，60级。",
	["{area:2627} lies in the far north-west of the {zone:1423}, west of the {area:2279} gates. Stand inside a green glowing patch on the ground (a {object:179747}; some are inside the ruined houses) and use the {item:18752}: up to three Terrordale Spirits (level 59-60) rise and attack. Their {spell:7713} lowers all your stats by 30%: fight them one at a time and use {spell:2878}. The patches come back quickly; several paladins can work side by side."] = "{area:2627}位于{zone:1423}最西北，{area:2279}大门以西。站在地上绿色发光的斑块里（是一个{object:179747}；有些在废墟房屋内），使用{item:18752}：最多三个恐惧谷幽灵（59-60级）会升起攻击。它们的{spell:7713}会把你所有属性降低30%：一次只打一个，并使用{spell:2878}。斑块恢复很快；几名圣骑士可以并肩作业。",
	["{item:14047} drops from humanoids of level 50 and up ({area:2255}'s Bruisers, the Scarlet Crusade in the Plaguelands, the {area:2577} ogres). {item:8836} is a Plaguelands herb ({skill:182} 220), common around {area:3197}. An {item:12360} is an alchemist's transmute from a {item:12359} and an {item:12363}, once every two days per alchemist: ask a guild alchemist early, or buy the bars. The Auction House sells all three."] = "{item:14047}由50级以上人形生物掉落（{area:2255}的打手、瘟疫之地的血色十字军、{area:2577}的食人魔）。{item:8836}是瘟疫之地的草药（{skill:182} 220），在{area:3197}一带常见。一个{item:12360}是炼金师用{item:12359}和{item:12363}转化来的，每位炼金师每两天一次：早点找公会炼金师，或者直接买锭。这三样拍卖行都有卖。",
	["{item:14047} x40"] = "{item:14047}×40",
	["{item:18749}, inside the {object:179746}"] = "{item:18749}，{object:179746}内",
	["{item:18752}, inside a green patch"] = "{item:18752}，在绿色斑块内",
	["{item:18792}, from the satchel"] = "{item:18792}，来自背包",
	["{item:8836} x10"] = "{item:8836}×10",
	["{npc:11406}, the priest trainer, walks about the {object:32386} in {zone:1455}'s {object:32362}. He gives you his censer for a donation of 150 gold, taken at the hand-in. Keep the censer."] = "{npc:11406}，牧师训练师，在{zone:1455}的{object:32362}中的{object:32386}一带走动。只要你捐150金币（交任务时收取），他就会把香炉给你。把香炉留着。",
	["{npc:1416} works in {zone:1453}'s {object:28027}. He forges the {item:18753} from your materials and 150 gold."] = "{npc:1416}在{zone:1453}的{object:28027}里工作。他用你的材料和150金币锻造{item:18753}。",
	["{npc:2357} breeds horses in {area:271}'s stable. She makes the {quest:7645} from the 20 biscuits and 50 gold, taken at the hand-in."] = "{npc:2357}在{area:271}的马厩里养马。她用20块饼干和50金币制作{quest:7645}，交任务时收取。",
	["{object:2160} quartermasters sell Enriched Manna Biscuits, five for 60 silver, once the {object:92525} is Friendly with you: {npc:10857} at {area:3197} or {npc:11536} at {area:2268}. Scourgestones and the Plaguelands quests raise the standing."] = "{object:2160}军需官出售强化玛纳饼干，五块60银，前提是{object:92525}对你好感达到友善：{area:3197}的{npc:10857}或{area:2268}的{npc:11536}。天灾石和瘟疫之地的任务可以提升声望。",
}

G["forever/collectibles/mounts/alliance/winterspring-frostsaber"] = {
	["The Forever client lists it at 200g and level 60. It runs at full speed yet needs no riding training at all, only Honored with the {faction:589}, so you can skip the 1,000g Journeyman Riding if this is your fast mount."] = "Forever客户端把它标为200金、60级。它以全速奔跑，却完全不需要骑术训练，只要对{faction:589}达到尊敬，所以如果这就是你的快速坐骑，你可以省下1000金的初级骑术。",
	["{npc:10618} stands on top of {area:2241} in the far north of {zone:1452}. Only the Alliance can earn the {faction:589}' favour, from level 58: three repeatable quests worth 50 each, about 840 turn-ins from Neutral to Exalted. Frostsaber Provisions is open from the start, Winterfall Intrusion from halfway through Neutral and Rampaging Giants from Honored. The Wintersaber Trainers Reputation guide takes you through it."] = "{npc:10618}站在{zone:1452}最北端的{area:2241}顶上。只有联盟能获得{faction:589}的好感，从58级开始：三个可重复任务，每个50点声望，从中立到崇拜大约要交840次。霜刃豹补给从一开始就能做，冬泉入侵从中立过半开始，狂暴巨人从尊敬开始。冬刃豹训练师声望攻略会带你走完。",
}

G["forever/collectibles/pets/donni-anthania"] = {
	["{npc:6367} has a farmhouse north of {area:87}. Each cat carrier costs 40s, 1g 60s for all four. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:6367}在{area:87}以北有一间农舍。每个猫咪笼40银，四个全买1金60银。每个宠物物品在使用时会教会对应的伙伴；之后目标仍保持勾选。",
}
